134	    >
135	      {/* Stats Panel - Compact on mobile */}
136	      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
137	        <div className="grid grid-cols-2 md:grid-cols-3 gap-2 md:gap-4">
138	          {/* Challenges Completed */}
