60	      // Mobile: use more of the screen, account for header and padding
61	      const maxWidth = viewport.width - 32; // 16px padding on each side
62	      const maxHeight = viewport.height - 200; // Header, buttons, and safe area
63	      return {
64	        width: Math.min(maxWidth, 600), // Cap at reasonable size
65	        height: Math.min(maxHeight, 500)
66	      };
67	    } else {
68	      // Desktop: comfortable centered canvas
69	      return {
70	        width: Math.min(800, viewport.width - 100),
71	        height: Math.min(600, viewport.height - 300)
72	      };
73	    }
74	  };
75	
76	  const canvasSize = getCanvasSize();
77	
78	  if (isMobile) {
79	    // Mobile: Full-screen layout with no padding, tools at top/bottom
80	    return (
81	      <div className="min-h-screen bg-gray-50 flex flex-col">
82	        {/* Mobile Header */}
83	        <header className="bg-white border-b border-gray-200 px-4 py-3 flex justify-between items-center">
84	          <button
85	            onClick={onNavigateHome}
86	            className="kid-button bg-secondary-500 hover:bg-secondary-600 active:bg-secondary-700 px-3 py-2 text-sm"
87	          >
88	            ← Home
89	          </button>
90	          {quotaExceeded && (
91	            <span className="text-xs text-red-600 font-semibold">⚠️ Storage full</span>
92	          )}
93	          
94	          <h1 className="font-bold text-primary-600 text-base truncate mx-2">
95	            {stencil ? `🎭 ${stencil.name}` : '🎨 Draw!'}
96	          </h1>
97	          
98	          {/* Clear Button */}
99	          <button 
100	            onClick={handleClearCanvas}
