   ```ts
   const LAST_DATE_KEY = 'daily:lastDate';
   const STREAK_KEY = 'daily:streak';

   export function todayISO(): string { /* UTC YYYY-MM-DD */ }
   export function yesterdayISO(): string { /* UTC YYYY-MM-DD minus 1 day */ }
   export function getDailyPrompt(): Prompt {
     const dayIndex = Math.floor(Date.now() / 86_400_000);
     return prompts[dayIndex % prompts.length];
   }
   export function useDailyChallenge(): DailyState {
     const [streak, setStreak] = useState<number>(0);
     useEffect(() => {
       const today = todayISO();
       const lastDate = storage.get<string | null>(LAST_DATE_KEY, null);
       const savedStreak = storage.get<number>(STREAK_KEY, 0);
       if (lastDate === today) { setStreak(savedStreak); }
       else if (lastDate === yesterdayISO()) {
         const next = savedStreak + 1;
         storage.set(LAST_DATE_KEY, today); storage.set(STREAK_KEY, next); setStreak(next);
       } else {
         storage.set(LAST_DATE_KEY, today); storage.set(STREAK_KEY, 1); setStreak(1);
       }
     }, []);
     return { dailyPrompt: getDailyPrompt(), streak };
   }
   ```

