import { useState } from 'react';
import StencilGallery from './Stencils/StencilGallery';
import { Stencil } from '../types/Stencil';
import { get as storageGet } from '../utils/storage';

interface HomePageProps {
  onNavigateToDrawing: () => void;
  onNavigateToStencil: (stencil: Stencil) => void;
  onNavigateToColorBlocks: () => void;
  onNavigateToSudoku: () => void;
  onNavigateToTetris: () => void;
  onNavigateToJellyVolleyball: () => void;
  onNavigateToSnake: () => void;
  onNavigateToMemoryMatch: () => void;
  onNavigateToDrawingChallenge: () => void;
  onNavigateToPopBalloons: () => void;
  onNavigateToSimonSays: () => void;
  onNavigateToBubblePop: () => void;
  onNavigateToColorMixer: () => void;
  onNavigateToMathFacts: () => void;
  onNavigateToShapeSorting: () => void;
  onNavigateToGallery: () => void;
}

function HomePage({ onNavigateToDrawing, onNavigateToStencil, onNavigateToColorBlocks, onNavigateToSudoku, onNavigateToTetris, onNavigateToJellyVolleyball, onNavigateToSnake, onNavigateToMemoryMatch, onNavigateToDrawingChallenge, onNavigateToPopBalloons, onNavigateToSimonSays, onNavigateToBubblePop, onNavigateToColorMixer, onNavigateToMathFacts, onNavigateToShapeSorting, onNavigateToGallery }: HomePageProps) {
  const [isExcited, setIsExcited] = useState(false);
  const [showStencils, setShowStencils] = useState(false);

  // Read drawing streak directly from storage (refreshes on every render / navigation back)
  const drawingStreak = storageGet<number>('daily:streak', 0);

  const handleStencilSelect = (stencil: Stencil) => {
    onNavigateToStencil(stencil);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-secondary-100 via-primary-50 to-secondary-50">
      {/* Header */}
      <header className="pt-8 pb-4 px-4 text-center">
        <h1 className="text-4xl md:text-6xl font-bold text-primary-600 mb-2">
          🎨 Kids Drawing App
        </h1>
        <p className="text-xl md:text-2xl text-gray-700 font-medium">
          Draw, Create, and Have Fun!
        </p>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 py-8">
        {/* Welcome Card */}
        <div className="kid-card max-w-2xl mx-auto text-center mb-8">
          <div className="text-6xl mb-4">
            {isExcited ? '🎉' : '✨'}
          </div>
          <h2 className="text-2xl md:text-3xl font-bold text-gray-800 mb-4">
            Welcome to Your Creative Space!
          </h2>
          <p className="text-lg text-gray-600 mb-6">
            A magical drawing app where you can create amazing artwork
            with your fingers, explore AI-powered stencils, and save your masterpieces!
          </p>

          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <button
              className="kid-button text-xl"
              onTouchStart={() => setIsExcited(true)}
              onClick={() => {
                setIsExcited(true);
                onNavigateToDrawing();
              }}
            >
              🖌️ Free Drawing!
            </button>

            <button
              className="kid-button bg-purple-500 hover:bg-purple-600 active:bg-purple-700 text-xl"
              onClick={() => {
                setIsExcited(true);
                setShowStencils(!showStencils);
              }}
              onTouchStart={() => setIsExcited(true)}
            >
              🎭 Color Stencils!
            </button>

            <button
              className="kid-button bg-secondary-500 hover:bg-secondary-600 active:bg-secondary-700 text-xl"
              onClick={() => setIsExcited(!isExcited)}
              onTouchStart={() => setIsExcited(true)}
            >
              {isExcited ? 'So Excited!' : 'Tell Me More!'}
            </button>
          </div>
        </div>

        {/* Games Section */}
        <div className="kid-card max-w-6xl mx-auto mb-8">
          <h2 className="text-2xl md:text-3xl font-bold text-gray-800 mb-4 text-center">
            🎮 Fun Games to Play!
          </h2>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {/* Color Blocks Game */}
            <button
              className="kid-card bg-green-500 hover:bg-green-600 active:bg-green-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-green-700"
              onClick={() => onNavigateToColorBlocks()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🎨</div>
              <div className="text-white font-bold text-lg">Color Blocks</div>
            </button>

            {/* Sudoku */}
            <button
              className="kid-card bg-blue-500 hover:bg-blue-600 active:bg-blue-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-blue-700"
              onClick={() => onNavigateToSudoku()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🧩</div>
              <div className="text-white font-bold text-lg">Sudoku</div>
            </button>

            {/* Tetris */}
            <button
              className="kid-card bg-orange-500 hover:bg-orange-600 active:bg-orange-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-orange-700"
              onClick={() => onNavigateToTetris()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🧱</div>
              <div className="text-white font-bold text-lg">Tetris</div>
            </button>

            {/* Jelly Volleyball */}
            <button
              className="kid-card bg-teal-500 hover:bg-teal-600 active:bg-teal-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-teal-700"
              onClick={() => onNavigateToJellyVolleyball()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🏐</div>
              <div className="text-white font-bold text-lg">Jelly Volleyball</div>
            </button>

            {/* Snake Game */}
            <button
              className="kid-card bg-lime-500 hover:bg-lime-600 active:bg-lime-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-lime-700"
              onClick={() => onNavigateToSnake()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🐍</div>
              <div className="text-white font-bold text-lg">Snake</div>
            </button>

            {/* Memory Match - NEW! */}
            <button
              className="kid-card bg-pink-500 hover:bg-pink-600 active:bg-pink-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-pink-700"
              onClick={() => onNavigateToMemoryMatch()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🃏</div>
              <div className="text-white font-bold text-lg">Memory Match</div>
            </button>

            {/* Drawing Challenge - NEW! */}
            <button
              className="kid-card bg-purple-500 hover:bg-purple-600 active:bg-purple-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-purple-700 relative"
              onClick={() => onNavigateToDrawingChallenge()}
              onTouchStart={() => setIsExcited(true)}
            >
              {drawingStreak > 0 && (
                <span className="absolute top-1 right-1 bg-orange-400 text-white text-xs font-bold rounded-full px-2 py-0.5 leading-none">
                  🔥 {drawingStreak}d
                </span>
              )}
              <div className="text-5xl mb-2">🎨</div>
              <div className="text-white font-bold text-lg">Drawing Challenge</div>
            </button>

            {/* Pop the Balloons - NEW! */}
            <button
              className="kid-card bg-yellow-500 hover:bg-yellow-600 active:bg-yellow-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-yellow-700"
              onClick={() => onNavigateToPopBalloons()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🎯</div>
              <div className="text-white font-bold text-lg">Pop Balloons</div>
            </button>

            {/* Simon Says - NEW! */}
            <button
              className="kid-card bg-indigo-500 hover:bg-indigo-600 active:bg-indigo-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-indigo-700"
              onClick={() => onNavigateToSimonSays()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🎵</div>
              <div className="text-white font-bold text-lg">Simon Says</div>
            </button>

            {/* Bubble Pop - NEW! */}
            <button
              className="kid-card bg-cyan-500 hover:bg-cyan-600 active:bg-cyan-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-cyan-700"
              onClick={() => onNavigateToBubblePop()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🫧</div>
              <div className="text-white font-bold text-lg">Bubble Pop</div>
            </button>

            {/* Color Mixer - NEW! */}
            <button
              className="kid-card bg-rose-500 hover:bg-rose-600 active:bg-rose-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-rose-700"
              onClick={() => onNavigateToColorMixer()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🎨</div>
              <div className="text-white font-bold text-lg">Color Mixer</div>
            </button>

            {/* Math Facts - NEW! */}
            <button
              className="kid-card bg-emerald-500 hover:bg-emerald-600 active:bg-emerald-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-emerald-700"
              onClick={() => onNavigateToMathFacts()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🔢</div>
              <div className="text-white font-bold text-lg">Math Facts</div>
            </button>

            {/* Shape Sorting - NEW! */}
            <button
              className="kid-card bg-amber-500 hover:bg-amber-600 active:bg-amber-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-amber-700"
              onClick={() => onNavigateToShapeSorting()}
              onTouchStart={() => setIsExcited(true)}
            >
              <div className="text-5xl mb-2">🎪</div>
              <div className="text-white font-bold text-lg">Shape Sorting</div>
            </button>

            {/* Gallery */}
            <button
              className="kid-card bg-violet-500 hover:bg-violet-600 active:bg-violet-700 transition-colors duration-200 p-6 text-center cursor-pointer border-2 border-transparent hover:border-violet-700"
              onClick={() => onNavigateToGallery()}
              onTouchStart={() => setIsExcited(true)}
              aria-label="Gallery"
            >
              <div className="text-5xl mb-2">🖼️</div>
              <div className="text-white font-bold text-lg">Gallery</div>
            </button>
          </div>
        </div>

        {/* Stencil Gallery */}
        {showStencils && (
          <div className="mb-8">
            <StencilGallery onStencilSelect={handleStencilSelect} />
          </div>
        )}

        {/* Features Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 max-w-4xl mx-auto">
          {/* Feature 1: Touch Drawing */}
          <div className="kid-card text-center">
            <div className="text-4xl mb-4">👆</div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Touch & Draw</h3>
            <p className="text-gray-600">
              Draw with your finger or stylus. Perfect for tablets and phones!
            </p>
          </div>

          {/* Feature 2: Colors */}
          <div className="kid-card text-center">
            <div className="text-4xl mb-4">🌈</div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Bright Colors</h3>
            <p className="text-gray-600">
              Choose from lots of beautiful colors to make your art pop!
            </p>
          </div>

          {/* Feature 3: Save Art */}
          <div className="kid-card text-center">
            <div className="text-4xl mb-4">💾</div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Save Your Art</h3>
            <p className="text-gray-600">
              Keep all your drawings safe and show them to family and friends!
            </p>
          </div>
        </div>

        {/* Coming Soon Section */}
        <div className="mt-12 text-center">
          <h3 className="text-2xl font-bold text-gray-700 mb-6">Coming Soon</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-2xl mx-auto">
            <div className="bg-white/50 rounded-2xl p-4 border-2 border-dashed border-primary-300">
              <div className="text-2xl mb-2">🤖</div>
              <p className="text-sm font-medium text-gray-600">AI Stencils</p>
            </div>
            <div className="bg-white/50 rounded-2xl p-4 border-2 border-dashed border-primary-300">
              <div className="text-2xl mb-2">🖌️</div>
              <p className="text-sm font-medium text-gray-600">More Brushes</p>
            </div>
            <div className="bg-white/50 rounded-2xl p-4 border-2 border-dashed border-primary-300">
              <div className="text-2xl mb-2">📱</div>
              <p className="text-sm font-medium text-gray-600">Mobile App</p>
            </div>
            <div className="bg-white/50 rounded-2xl p-4 border-2 border-dashed border-primary-300">
              <div className="text-2xl mb-2">☁️</div>
              <p className="text-sm font-medium text-gray-600">Cloud Save</p>
            </div>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="mt-12 pb-8 text-center text-gray-500">
        <p className="text-sm">
          Made with ❤️ for creative kids everywhere
        </p>
        <p className="text-xs mt-2">
          v0.1.6 - Enhanced High-Quality Stencils!
        </p>
        <p className="text-xs mt-1 font-mono text-gray-400">
          Build: {__COMMIT_HASH__}
        </p>
      </footer>
    </div>
  );
}

export default HomePage;

import { useEffect, useState } from 'react';
import HomePage from './components/HomePage';
import { migrate } from './utils/storage';
import DrawingPage from './components/DrawingPage';
import ColorBlocksPage from './components/Games/ColorBlocksGame/ColorBlocksPage';
import { Stencil } from './types/Stencil';
import SudokuPage from './components/Games/Sudoku/SudokuPage';
import TetrisPage from './components/Games/Tetris/TetrisPage';
import JellyVolleyballPage from './components/Games/JellyVolleyball/JellyVolleyballPage';
import SnakePage from './components/Games/Snake/SnakePage';
import MemoryMatchPage from './components/Games/MemoryMatch/MemoryMatchPage';
import DrawingChallengePage from './components/Games/DrawingChallenge/DrawingChallengePage';
import PopBalloonsPage from './components/Games/PopBalloons/PopBalloonsPage';
import SimonSaysPage from './components/Games/SimonSays/SimonSaysPage';
import BubblePopPage from './components/Games/BubblePop/BubblePopPage';
import ColorMixerPage from './components/Games/ColorMixer/ColorMixerPage';
import MathFactsPage from './components/Games/MathFacts/MathFactsPage';
import ShapeSortingPage from './components/Games/ShapeSorting/ShapeSortingPage';
import DrawingGallery from './components/Gallery/DrawingGallery';
import { SavedDrawing } from './hooks/useDrawings';

type AppPage = 'home' | 'draw' | 'stencil' | 'colorblocks' | 'sudoku' | 'tetris' | 'jellyvolleyball' | 'snake' | 'memoryMatch' | 'drawingChallenge' | 'popBalloons' | 'simonSays' | 'bubblePop' | 'colorMixer' | 'mathFacts' | 'shapeSorting' | 'gallery';

function App() {
  const [currentPage, setCurrentPage] = useState<AppPage>('home');
  const [selectedStencil, setSelectedStencil] = useState<Stencil | null>(null);
  const [drawingToLoad, setDrawingToLoad] = useState<string | null>(null);

  // One-time migration of legacy un-prefixed keys to the kda: storage namespace
  useEffect(() => {
    migrate();
  }, []);

  const navigateTo = (page: AppPage) => {
    if (page === 'home') setDrawingToLoad(null);
    setCurrentPage(page);
  };

  const navigateToStencil = (stencil: Stencil) => {
    setSelectedStencil(stencil);
    setCurrentPage('stencil');
  };

  const navigateToDrawFromGallery = (drawing: SavedDrawing) => {
    setDrawingToLoad(drawing.dataURL);
    setCurrentPage('draw');
  };

  const renderCurrentPage = () => {
    switch (currentPage) {
      case 'home':
        return (
<HomePage
            onNavigateToDrawing={() => navigateTo('draw')}
            onNavigateToStencil={navigateToStencil}
            onNavigateToColorBlocks={() => navigateTo('colorblocks')}
            onNavigateToSudoku={() => navigateTo('sudoku')}
            onNavigateToTetris={() => navigateTo('tetris')}
            onNavigateToJellyVolleyball={() => navigateTo('jellyvolleyball')}
            onNavigateToSnake={() => navigateTo('snake')}
            onNavigateToMemoryMatch={() => navigateTo('memoryMatch')}
            onNavigateToDrawingChallenge={() => navigateTo('drawingChallenge')}
            onNavigateToPopBalloons={() => navigateTo('popBalloons')}
            onNavigateToSimonSays={() => navigateTo('simonSays')}
            onNavigateToBubblePop={() => navigateTo('bubblePop')}
            onNavigateToColorMixer={() => navigateTo('colorMixer')}
            onNavigateToMathFacts={() => navigateTo('mathFacts')}
            onNavigateToShapeSorting={() => navigateTo('shapeSorting')}
            onNavigateToGallery={() => navigateTo('gallery')}
          />
        );
      case 'draw':
        return (
          <DrawingPage
            onNavigateHome={() => navigateTo('home')}
            initialDataURL={drawingToLoad ?? undefined}
          />
        );
      case 'stencil':
        return (
          <DrawingPage 
            onNavigateHome={() => navigateTo('home')} 
            stencil={selectedStencil}
          />
        );
      case 'colorblocks':
        return <ColorBlocksPage onNavigateHome={() => navigateTo('home')} />;
      case 'sudoku':
        return (
          <SudokuPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'tetris':
        return (
          <TetrisPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'jellyvolleyball':
        return (
          <JellyVolleyballPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'snake':
        return (
          <SnakePage onNavigateHome={() => navigateTo('home')} />
        );
      case 'memoryMatch':
        return (
          <MemoryMatchPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'drawingChallenge':
        return (
          <DrawingChallengePage onNavigateHome={() => navigateTo('home')} />
        );
      case 'popBalloons':
        return (
          <PopBalloonsPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'simonSays':
        return (
          <SimonSaysPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'bubblePop':
        return (
          <BubblePopPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'colorMixer':
        return (
          <ColorMixerPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'mathFacts':
        return (
          <MathFactsPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'shapeSorting':
        return (
          <ShapeSortingPage onNavigateHome={() => navigateTo('home')} />
        );
      case 'gallery':
        return (
          <DrawingGallery
            onNavigateHome={() => navigateTo('home')}
            onEditDrawing={navigateToDrawFromGallery}
          />
        );
      default:
        return (
<HomePage
            onNavigateToDrawing={() => navigateTo('draw')}
            onNavigateToStencil={navigateToStencil}
            onNavigateToColorBlocks={() => navigateTo('colorblocks')}
            onNavigateToSudoku={() => navigateTo('sudoku')}
            onNavigateToTetris={() => navigateTo('tetris')}
            onNavigateToJellyVolleyball={() => navigateTo('jellyvolleyball')}
            onNavigateToSnake={() => navigateTo('snake')}
            onNavigateToMemoryMatch={() => navigateTo('memoryMatch')}
            onNavigateToDrawingChallenge={() => navigateTo('drawingChallenge')}
            onNavigateToPopBalloons={() => navigateTo('popBalloons')}
            onNavigateToSimonSays={() => navigateTo('simonSays')}
            onNavigateToBubblePop={() => navigateTo('bubblePop')}
            onNavigateToColorMixer={() => navigateTo('colorMixer')}
            onNavigateToMathFacts={() => navigateTo('mathFacts')}
            onNavigateToShapeSorting={() => navigateTo('shapeSorting')}
            onNavigateToGallery={() => navigateTo('gallery')}
          />
        );
    }
  };

  return (
    <div>
      {renderCurrentPage()}
    </div>
  );
}

export default App;

import { useState, useCallback, useEffect, useRef } from 'react';
import DrawingCanvasWithTools from './Canvas/DrawingCanvasWithTools';
import { isMobileDevice, getViewportDimensions } from '../utils/DeviceUtils';
import { Stencil } from '../types/Stencil';
import { useDrawings } from '../hooks/useDrawings';

interface DrawingPageProps {
  onNavigateHome: () => void;
  stencil?: Stencil | null;
  initialDataURL?: string;
}

const DrawingPage = ({ onNavigateHome, stencil, initialDataURL }: DrawingPageProps) => {
  const [isMobile, setIsMobile] = useState(false);
  const [viewport, setViewport] = useState({ width: 800, height: 600 });
  const [quotaExceeded, setQuotaExceeded] = useState(false);
  const clearCanvasRef = useRef<(() => void) | null>(null);
  const { save } = useDrawings();

  const handleDrawingChange = useCallback((dataURL: string) => {
    try {
      save(dataURL);
      setQuotaExceeded(false);
    } catch {
      setQuotaExceeded(true);
    }
  }, [save]);

  const handleClearCanvas = useCallback(() => {
    if (clearCanvasRef.current) {
      clearCanvasRef.current();
    }
  }, []);

  // Detect mobile and calculate optimal canvas size
  useEffect(() => {
    const updateLayout = () => {
      const mobile = isMobileDevice();
      const dimensions = getViewportDimensions();

      setIsMobile(mobile);
      setViewport(dimensions);
    };

    updateLayout();

    window.addEventListener('resize', updateLayout);
    window.addEventListener('orientationchange', updateLayout);

    return () => {
      window.removeEventListener('resize', updateLayout);
      window.removeEventListener('orientationchange', updateLayout);
    };
  }, []);


  // Calculate optimal canvas size based on device and viewport
  const getCanvasSize = () => {
    if (isMobile) {
      // Mobile: use more of the screen, account for header and padding
      const maxWidth = viewport.width - 32; // 16px padding on each side
      const maxHeight = viewport.height - 200; // Header, buttons, and safe area
      return {
        width: Math.min(maxWidth, 600), // Cap at reasonable size
        height: Math.min(maxHeight, 500)
      };
    } else {
      // Desktop: comfortable centered canvas
      return {
        width: Math.min(800, viewport.width - 100),
        height: Math.min(600, viewport.height - 300)
      };
    }
  };

  const canvasSize = getCanvasSize();

  if (isMobile) {
    // Mobile: Full-screen layout with no padding, tools at top/bottom
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        {/* Mobile Header */}
        <header className="bg-white border-b border-gray-200 px-4 py-3 flex justify-between items-center">
          <button
            onClick={onNavigateHome}
            className="kid-button bg-secondary-500 hover:bg-secondary-600 active:bg-secondary-700 px-3 py-2 text-sm"
          >
            ← Home
          </button>
          {quotaExceeded && (
            <span className="text-xs text-red-600 font-semibold">⚠️ Storage full</span>
          )}

          <h1 className="font-bold text-primary-600 text-base truncate mx-2">
            {stencil ? `🎭 ${stencil.name}` : '🎨 Draw!'}
          </h1>

          {/* Clear Button */}
          <button 
            onClick={handleClearCanvas}
            className="kid-button bg-red-500 hover:bg-red-600 active:bg-red-700 px-3 py-2 text-sm flex items-center gap-1"
          >
            <span>🗑️</span>
            Clear
          </button>
        </header>

        {/* Memory full banner */}
        {quotaExceeded && (
          <div className="bg-yellow-100 border-b border-yellow-300 px-4 py-2 text-sm text-yellow-800 text-center">
            📱 Memory full! Tap a drawing in the Gallery to delete some.
          </div>
        )}

        {/* Canvas with Tools - takes remaining space */}
        <main className="flex-1 flex flex-col">
          <DrawingCanvasWithTools
            width={canvasSize.width}
            height={canvasSize.height}
            className="h-full"
            onDrawingChange={handleDrawingChange}
            clearCanvasRef={clearCanvasRef}
            stencil={stencil}
            initialDataURL={initialDataURL}
          />
        </main>
      </div>
    );
  }

  // Desktop: Keep the existing layout
  return (
    <div className="min-h-screen bg-gradient-to-br from-secondary-100 via-primary-50 to-secondary-50 p-4">
      {/* Header */}
      <header className="flex justify-between items-center mb-6">
        <button 
          onClick={onNavigateHome}
          className="kid-button bg-secondary-500 hover:bg-secondary-600 active:bg-secondary-700 px-4 py-2 text-sm"
        >
          ← Home
        </button>

        <h1 className="font-bold text-primary-600 text-2xl md:text-3xl">
          {stencil 
            ? `🎭 Color ${stencil.name}!`
            : '🎨 Draw Something Amazing!'
          }
        </h1>

        {/* Spacer for layout balance */}
        <div className="w-16"></div>
      </header>

      {/* Drawing Area */}
      <main className="flex justify-center">
        <div className="kid-card max-w-4xl w-full">
          <div className="flex flex-col items-center space-y-4">
            <p className="text-lg text-gray-600 text-center">
              {stencil 
                ? `Fill in the ${stencil.name.toLowerCase()} with colors and patterns!`
                : 'Use your finger or stylus to draw on the canvas below'
              }
            </p>

            {/* Canvas with Tools Container */}
            <div className="w-full flex justify-center">
              <DrawingCanvasWithTools
                width={canvasSize.width}
                height={canvasSize.height}
                className="max-w-full"
                onDrawingChange={handleDrawingChange}
                clearCanvasRef={clearCanvasRef}
                stencil={stencil}
              />
            </div>

            {/* Instructions */}
            <div className="text-center text-gray-500 text-sm max-w-md">
              <p className="mb-2">📱 <strong>On mobile:</strong> Draw with your finger</p>
              <p>🖥️ <strong>On desktop:</strong> Click and drag to draw</p>
            </div>
          </div>
        </div>
      </main>

      {/* Footer Info */}
      <footer className="mt-8 text-center text-sm">
        {quotaExceeded ? (
          <p className="text-yellow-700 font-semibold">
            📱 Memory full! Tap a drawing in the Gallery to delete some.
          </p>
        ) : (
          <p className="text-gray-500">✨ Your drawing will be automatically saved when you're done!</p>
        )}
      </footer>
    </div>
  );
};

export default DrawingPage;

import { renderHook } from '@testing-library/react';
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { useDailyChallenge } from './useDailyChallenge';
import * as storage from '../utils/storage';

// Fixed reference date: 2024-06-15 (Saturday)
const TODAY = new Date('2024-06-15T10:00:00Z');
const TODAY_ISO = '2024-06-15';
const YESTERDAY_ISO = '2024-06-14';
const FOUR_DAYS_AGO_ISO = '2024-06-11';

describe('useDailyChallenge — streak logic', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.useFakeTimers();
    vi.setSystemTime(TODAY);
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('first-ever load: lastDate=null → streak becomes 1', () => {
    // Storage is empty (never visited)
    const { result } = renderHook(() => useDailyChallenge());

    expect(result.current.streak).toBe(1);
    // Verify storage was written
    expect(storage.get('daily:lastDate', null)).toBe(TODAY_ISO);
    expect(storage.get('daily:streak', 0)).toBe(1);
  });

  it('same-day reload: lastDate=today → streak unchanged', () => {
    storage.set('daily:lastDate', TODAY_ISO);
    storage.set('daily:streak', 5);

    const { result } = renderHook(() => useDailyChallenge());

    expect(result.current.streak).toBe(5);
    // Storage should not have been touched (same values)
    expect(storage.get('daily:streak', 0)).toBe(5);
  });

  it('next-day load: lastDate=yesterday → streak increments by 1', () => {
    storage.set('daily:lastDate', YESTERDAY_ISO);
    storage.set('daily:streak', 3);

    const { result } = renderHook(() => useDailyChallenge());

    expect(result.current.streak).toBe(4);
    expect(storage.get('daily:lastDate', null)).toBe(TODAY_ISO);
    expect(storage.get('daily:streak', 0)).toBe(4);
  });

  it('3-day gap: lastDate=4 days ago → streak resets to 1', () => {
    storage.set('daily:lastDate', FOUR_DAYS_AGO_ISO);
    storage.set('daily:streak', 10);

    const { result } = renderHook(() => useDailyChallenge());

    expect(result.current.streak).toBe(1);
    expect(storage.get('daily:lastDate', null)).toBe(TODAY_ISO);
    expect(storage.get('daily:streak', 0)).toBe(1);
  });

  it('returns a valid daily prompt (deterministic for same day)', () => {
    const { result: r1 } = renderHook(() => useDailyChallenge());
    const { result: r2 } = renderHook(() => useDailyChallenge());

    expect(r1.current.dailyPrompt).toBeDefined();
    expect(r1.current.dailyPrompt.id).toBe(r2.current.dailyPrompt.id);
    expect(r1.current.dailyPrompt.text).toBeTruthy();
  });

  it('daily prompt is a valid Prompt on any day', () => {
    vi.setSystemTime(new Date('2024-06-30T12:00:00Z'));
    const { result } = renderHook(() => useDailyChallenge());

    expect(result.current.dailyPrompt).toBeDefined();
    expect(typeof result.current.dailyPrompt.id).toBe('string');
    expect(typeof result.current.dailyPrompt.text).toBe('string');
    expect(typeof result.current.dailyPrompt.emoji).toBe('string');
  });
});

/**
 * Drawing Challenge Game Page
 * Shows prompts and integrates with drawing canvas
 */

import React, { useState, useCallback, useRef } from 'react';
import { useDrawingChallenge } from '../../../hooks/useDrawingChallenge';
import GameLayout from '../../shared/GameLayout';
import DrawingCanvasWithTools from '../../Canvas/DrawingCanvasWithTools';
import type { Category, GameMode } from './types';
import { categoryNames } from './prompts';
import { formatTime } from '../../../utils/gameUtils';

interface DrawingChallengePageProps {
  onNavigateHome: () => void;
}

const DrawingChallengePage: React.FC<DrawingChallengePageProps> = ({ onNavigateHome }) => {
  const {
    gameState,
    daily,
    startChallenge,
    finishChallenge,
    nextPrompt,
    setCategory,
    setMode,
    setTimeLimit
  } = useDrawingChallenge();

  const {
    currentPrompt,
    gameStatus,
    mode,
    category,
    timeLimit,
    timeRemaining,
    completedChallenges
  } = gameState;

  const [showCanvas, setShowCanvas] = useState(false);
  const clearCanvasRef = useRef<(() => void) | null>(null);

  const handleStartDrawing = useCallback(() => {
    startChallenge();
    setShowCanvas(true);
  }, [startChallenge]);

  const handleFinish = useCallback(() => {
    finishChallenge();
    setShowCanvas(false);
  }, [finishChallenge]);

  const handleNextPrompt = useCallback(() => {
    nextPrompt();
    setShowCanvas(false);
    if (clearCanvasRef.current) {
      clearCanvasRef.current();
    }
  }, [nextPrompt]);

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setCategory(e.target.value as Category);
    setShowCanvas(false);
  };

  const handleModeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setMode(e.target.value as GameMode);
    setShowCanvas(false);
  };

  const handleTimeLimitChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setTimeLimit(parseInt(e.target.value, 10));
  };

  const handleClearCanvas = useCallback(() => {
    if (clearCanvasRef.current) {
      clearCanvasRef.current();
    }
  }, []);

  const headerActions = (
    <>
      {/* Category Selector - Compact on mobile */}
      <select
        value={category}
        onChange={handleCategoryChange}
        disabled={gameStatus === 'drawing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Drawing Category"
      >
        {Object.entries(categoryNames).map(([key, name]) => (
          <option key={key} value={key}>
            {name}
          </option>
        ))}
      </select>

      {/* Mode Selector - Compact on mobile */}
      <select
        value={mode}
        onChange={handleModeChange}
        disabled={gameStatus === 'drawing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Game Mode"
      >
        <option value="free">✨ Free</option>
        <option value="timed">⏱️ Timed</option>
      </select>

      {/* Time Limit Selector (only in timed mode) - Compact on mobile */}
      {mode === 'timed' && (
        <select
          value={timeLimit}
          onChange={handleTimeLimitChange}
          disabled={gameStatus === 'drawing'}
          className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
          title="Time Limit"
        >
          <option value={60}>1m</option>
          <option value={120}>2m</option>
          <option value={180}>3m</option>
          <option value={300}>5m</option>
        </select>
      )}
    </>
  );

  return (
    <GameLayout
      title="Drawing Challenge"
      emoji="🎨"
      onNavigateHome={onNavigateHome}
      headerActions={headerActions}
      bgColorClass="bg-gradient-to-b from-purple-100 to-pink-100"
    >
      {/* Daily Challenge Banner */}
      {!showCanvas && (
        <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-3 md:p-5 bg-gradient-to-r from-yellow-100 to-orange-100 border-2 border-yellow-300">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div>
              <p className="text-xs md:text-sm font-bold text-yellow-700 uppercase tracking-wide mb-1">
                🌟 Today's Challenge
              </p>
              <p className="text-lg md:text-2xl font-bold text-orange-700">
                {daily.dailyPrompt.emoji} Draw a {daily.dailyPrompt.text}!
              </p>
            </div>
            <div className="text-center">
              {daily.streak > 0 ? (
                <>
                  <p className="text-2xl md:text-3xl font-bold text-orange-500">
                    🔥 Day {daily.streak}
                  </p>
                  <p className="text-xs text-orange-600 font-semibold">streak!</p>
                </>
              ) : (
                <p className="text-sm font-semibold text-yellow-700">
                  Start your streak today!
                </p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Stats Panel - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-2 md:grid-cols-3 gap-2 md:gap-4">
          {/* Challenges Completed */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Completed</p>
            <p className="text-xl md:text-3xl font-bold text-green-600">
              {completedChallenges.length}
            </p>
          </div>

          {/* Current Difficulty */}
          {currentPrompt && (
            <div className="text-center">
              <p className="text-xs md:text-sm text-slate-600 font-semibold">Difficulty</p>
              <p className="text-xl md:text-3xl font-bold text-purple-600">
                {currentPrompt.difficulty === 1 ? '⭐' : currentPrompt.difficulty === 2 ? '⭐⭐' : '⭐⭐⭐'}
              </p>
            </div>
          )}

          {/* Timer (timed mode only) */}
          {mode === 'timed' && gameStatus === 'drawing' && (
            <div className="text-center">
              <p className="text-xs md:text-sm text-slate-600 font-semibold">Time Left</p>
              <p className={`text-xl md:text-3xl font-bold ${timeRemaining < 30 ? 'text-red-600' : 'text-blue-600'}`}>
                {formatTime(timeRemaining)}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Prompt Display (when not drawing) - Compact on mobile */}
      {!showCanvas && currentPrompt && (
        <div className="max-w-2xl mx-auto mb-2 md:mb-6">
          <div className="kid-card text-center bg-white p-4 md:p-8">
            <div className="text-5xl md:text-8xl mb-2 md:mb-4 animate-bounce-once">
              {currentPrompt.emoji}
            </div>
            <h2 className="text-2xl md:text-4xl font-bold text-purple-700 mb-2">
              Draw a {currentPrompt.text}!
            </h2>
            <p className="text-sm md:text-lg text-slate-600 mb-4 md:mb-6">
              {mode === 'timed'
                ? `You have ${formatTime(timeLimit)} to draw it!`
                : 'Take your time and be creative!'}
            </p>

            <div className="flex gap-2 md:gap-3 justify-center flex-wrap">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-base md:text-xl px-4 md:px-8"
                onClick={handleStartDrawing}
              >
                🖌️ Start Drawing!
              </button>

              {gameStatus !== 'drawing' && (
                <button
                  className="kid-button bg-blue-500 hover:bg-blue-600 text-base md:text-xl px-4 md:px-8"
                  onClick={handleNextPrompt}
                >
                  🎲 Different Prompt
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Drawing Canvas (when drawing) */}
      {showCanvas && currentPrompt && (
        <div className="max-w-4xl mx-auto">
          {/* Prompt reminder */}
          <div className="kid-card bg-white p-4 mb-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-4xl">{currentPrompt.emoji}</span>
              <div>
                <p className="text-sm text-slate-600">Drawing:</p>
                <p className="text-2xl font-bold text-purple-700">
                  {currentPrompt.text}
                </p>
              </div>
            </div>

            {mode === 'timed' && (
              <div className="text-right">
                <p className="text-sm text-slate-600">Time Left</p>
                <p className={`text-3xl font-bold ${timeRemaining < 30 ? 'text-red-600 animate-pulse' : 'text-blue-600'}`}>
                  {formatTime(timeRemaining)}
                </p>
              </div>
            )}
          </div>

          {/* Canvas */}
          <div className="kid-card bg-white p-4 mb-4">
            <DrawingCanvasWithTools
              width={600}
              height={450}
              onDrawingChange={() => {
                // Could save drawing here if needed
                console.log('Drawing updated');
              }}
              clearCanvasRef={clearCanvasRef}
            />
          </div>

          {/* Drawing Controls */}
          <div className="flex gap-3 justify-center flex-wrap">
            <button
              className="kid-button bg-green-500 hover:bg-green-600 text-lg px-6"
              onClick={handleFinish}
            >
              ✅ I'm Done!
            </button>

            <button
              className="kid-button bg-orange-500 hover:bg-orange-600 text-lg px-6"
              onClick={handleClearCanvas}
            >
              🗑️ Clear Canvas
            </button>

            <button
              className="kid-button bg-slate-500 hover:bg-slate-600 text-lg px-6"
              onClick={() => {
                setShowCanvas(false);
                if (gameStatus === 'drawing') {
                  handleFinish();
                }
              }}
            >
              ⬅️ Back to Prompt
            </button>
          </div>
        </div>
      )}

      {/* Instructions - Hidden on mobile */}
      {!showCanvas && (
        <div className="kid-card max-w-4xl mx-auto mt-6 hidden md:block">
          <h2 className="text-xl font-bold mb-3 text-center text-purple-800">
            How to Play
          </h2>

          <div className="space-y-3 text-slate-700">
            <div>
              <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
              <p>
                Draw the object shown in the prompt! Be as creative as you want!
              </p>
            </div>

            <div>
              <h3 className="font-semibold text-lg mb-1">🎮 How to Play</h3>
              <ul className="list-disc list-inside space-y-1">
                <li>Choose a category (animals, food, nature, vehicles, or all)</li>
                <li>Pick free mode (no timer) or timed mode (race against the clock)</li>
                <li>Click "Start Drawing" to begin</li>
                <li>Draw the object using the canvas tools</li>
                <li>Click "I'm Done!" when finished</li>
                <li>Get a new prompt and keep drawing!</li>
              </ul>
            </div>

            <div>
              <h3 className="font-semibold text-lg mb-1">🎨 Modes</h3>
              <ul className="list-disc list-inside space-y-1">
                <li><strong>Free Mode:</strong> Take your time and be creative with no pressure!</li>
                <li><strong>Timed Mode:</strong> Challenge yourself to draw within a time limit!</li>
              </ul>
            </div>

            <div>
              <h3 className="font-semibold text-lg mb-1">💡 Tips</h3>
              <ul className="list-disc list-inside space-y-1">
                <li>There's no wrong way to draw!</li>
                <li>Use different colors to make it fun</li>
                <li>Keep challenging yourself with harder prompts</li>
                <li>Complete all {120}+ drawing challenges!</li>
              </ul>
            </div>
          </div>
        </div>
      )}

      {/* Completion Message */}
      {gameStatus === 'finished' && !showCanvas && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <div className="text-6xl mb-4">🎉</div>
            <h2 className="text-3xl font-bold text-green-600 mb-4">
              Great Job!
            </h2>

            <p className="text-lg text-slate-700 mb-6">
              You completed the drawing challenge!
            </p>

            <div className="mb-4">
              <p className="text-sm text-slate-600">Challenges Completed</p>
              <p className="text-4xl font-bold text-purple-600">
                {completedChallenges.length}
              </p>
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-lg"
                onClick={() => {
                  handleNextPrompt();
                }}
              >
                🎲 Next Challenge
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default DrawingChallengePage;

