23	
24	function App() {
25	  const [currentPage, setCurrentPage] = useState<AppPage>('home');
26	  const [selectedStencil, setSelectedStencil] = useState<Stencil | null>(null);
27	  const [drawingToLoad, setDrawingToLoad] = useState<string | null>(null);
28	
29	  // One-time migration of legacy un-prefixed keys to the kda: storage namespace
30	  useEffect(() => {
31	    migrate();
