50	    switch (currentPage) {
51	      case 'home':
52	        return (
53	<HomePage
54	            onNavigateToDrawing={() => navigateTo('draw')}
55	            onNavigateToStencil={navigateToStencil}
56	            onNavigateToColorBlocks={() => navigateTo('colorblocks')}
