/**
 * Simon Says Game Page
 * Pattern memory game with colored buttons and audio feedback
 */

import React from 'react';
import { useSimonSays } from '../../../hooks/useSimonSays';
import GameLayout from '../../shared/GameLayout';
import type { Speed, ButtonConfig } from './types';
import { useWinCelebration } from '../../../hooks/useWinCelebration';

interface SimonSaysPageProps {
  onNavigateHome: () => void;
}

const buttonConfigs: ButtonConfig[] = [
  { color: 'red', frequency: 261.63, className: 'bg-red-500 hover:bg-red-600 active:bg-red-700' },
  { color: 'blue', frequency: 329.63, className: 'bg-blue-500 hover:bg-blue-600 active:bg-blue-700' },
  { color: 'green', frequency: 392.00, className: 'bg-green-500 hover:bg-green-600 active:bg-green-700' },
  { color: 'yellow', frequency: 523.25, className: 'bg-yellow-500 hover:bg-yellow-600 active:bg-yellow-700' }
];

const SimonSaysPage: React.FC<SimonSaysPageProps> = ({ onNavigateHome }) => {
  const { gameState, startGame, handleButtonPress, resetGame, setSpeed } = useSimonSays();

  const { round, gameStatus, speed, highScore, showingIndex } = gameState;

  useWinCelebration(
    gameStatus === 'gameOver',
    round === highScore && round > 1,
  );

  const getStatusMessage = (): string => {
    switch (gameStatus) {
      case 'ready':
        return '👆 Press Start to play!';
      case 'showing':
        return '👀 Watch the pattern!';
      case 'playing':
        return '🎯 Your turn!';
      case 'gameOver':
        return '💥 Game Over!';
      default:
        return '';
    }
  };

  const getStatusColor = (): string => {
    switch (gameStatus) {
      case 'ready':
        return 'text-blue-600';
      case 'showing':
        return 'text-purple-600';
      case 'playing':
        return 'text-green-600';
      case 'gameOver':
        return 'text-red-600';
      default:
        return 'text-slate-600';
    }
  };

  const headerActions = (
    <>
      {/* Speed buttons */}
      <div className="flex gap-1" title="Game Speed">
        {([['slow', '🐌', 'Slow'], ['normal', '🏃', 'Normal'], ['fast', '⚡', 'Fast']] as const).map(([val, icon, label]) => (
          <button
            key={val}
            aria-label={label}
            onClick={() => setSpeed(val as Speed)}
            disabled={gameStatus === 'showing' || gameStatus === 'playing'}
            className={`kid-button text-base md:text-lg px-2 md:px-3 py-1 md:py-2 ${speed === val ? '' : 'opacity-50'}`}
          >
            {icon}
          </button>
        ))}
      </div>

      {/* Reset Button - Compact on mobile */}
      {gameStatus !== 'ready' && (
        <button
          className="kid-button text-xs md:text-sm bg-blue-500 hover:bg-blue-600 px-2 md:px-4 py-1 md:py-2"
          onClick={resetGame}
        >
          <span className="md:hidden">🔄</span>
          <span className="hidden md:inline">🔄 New Game</span>
        </button>
      )}
    </>
  );

  return (
    <GameLayout
      title="Simon Says"
      emoji="🎵"
      onNavigateHome={onNavigateHome}
      headerActions={headerActions}
      bgColorClass="bg-gradient-to-b from-indigo-100 to-purple-100"
    >
      {/* Stats Panel - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-2 gap-2 md:gap-4">
          {/* Round */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Round</p>
            <p className="text-xl md:text-3xl font-bold text-purple-600">{round}</p>
          </div>

          {/* High Score */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Best</p>
            <p className="text-xl md:text-3xl font-bold text-yellow-600">{highScore}</p>
          </div>
        </div>
      </div>

      {/* Status Message - Smaller on mobile */}
      <div className="text-center mb-2 md:mb-4">
        <p className={`text-sm md:text-lg font-semibold ${getStatusColor()}`}>
          {getStatusMessage()}
        </p>
      </div>

      {/* Start Button */}
      {gameStatus === 'ready' && (
        <div className="text-center mb-4 md:mb-6">
          <button
            className="kid-button bg-purple-500 hover:bg-purple-600 text-lg md:text-2xl px-8 md:px-16 py-3 md:py-5"
            onClick={startGame}
          >
            🎵 Start Game!
          </button>
        </div>
      )}

      {/* Simon Buttons Grid */}
      <div className="max-w-md mx-auto mb-4 md:mb-6">
        <div className="grid grid-cols-2 gap-3 md:gap-4 p-4">
          {buttonConfigs.map((config, index) => {
            const glyphs = ['R', 'B', 'G', 'Y'];
            const emojis = ['🔴', '🔵', '🟢', '🟡'];
            return (
              <button
                key={config.color}
                aria-label={config.color}
                onClick={() => handleButtonPress(index)}
                disabled={gameStatus !== 'playing'}
                className={`
                  ${config.className}
                  ${showingIndex === index ? 'ring-8 ring-white scale-110' : ''}
                  ${gameStatus === 'playing' ? 'cursor-pointer' : 'cursor-not-allowed opacity-60'}
                  aspect-square rounded-2xl md:rounded-3xl
                  shadow-lg transition-all duration-200
                  flex items-center justify-center
                  text-white font-bold text-2xl md:text-4xl
                  touch-none select-none
                `}
                style={{
                  transform: showingIndex === index ? 'scale(1.1)' : 'scale(1)'
                }}
              >
                <span className="drop-shadow-lg flex flex-col items-center gap-0.5">
                  <span aria-hidden="true">{emojis[index]}</span>
                  <span className="text-sm md:text-base font-black leading-none">{glyphs[index]}</span>
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Instructions - Hidden on mobile */}
      <div className="kid-card max-w-4xl mx-auto hidden md:block">
        <h2 className="text-xl font-bold mb-3 text-center text-purple-800">
          How to Play
        </h2>

        <div className="space-y-3 text-slate-700">
          <div>
            <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
            <p>
              Repeat the pattern by pressing the buttons in the same order Simon shows you!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">🎮 How to Play</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Watch as Simon lights up buttons in a sequence</li>
              <li>Listen to the musical tones for each button</li>
              <li>Repeat the pattern by pressing the same buttons in order</li>
              <li>Each round adds one more button to the sequence</li>
              <li>One mistake and the game is over!</li>
            </ul>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⚙️ Speed Settings</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><strong>Slow:</strong> 800ms between buttons - great for learning</li>
              <li><strong>Normal:</strong> 600ms - standard challenge</li>
              <li><strong>Fast:</strong> 400ms - expert mode!</li>
            </ul>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">💡 Tips</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Pay attention to both colors and sounds</li>
              <li>Create a rhythm or pattern to remember the sequence</li>
              <li>Stay focused - one wrong button ends the game!</li>
              <li>Try to beat your high score!</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Game Over Modal */}
      {gameStatus === 'gameOver' && (
        <div className="fixed inset-0 bg-gradient-to-b from-purple-50/90 to-pink-50/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <div className="text-6xl mb-4">😅</div>
            <h2 className="text-3xl font-bold text-red-600 mb-4">
              Game Over!
            </h2>

            <div className="mb-6">
              <p className="text-lg text-slate-600">You reached round</p>
              <p className="text-5xl font-bold text-purple-600 my-2">{round}</p>

              {round === highScore && round > 1 && (
                <div className="bg-yellow-100 border-2 border-yellow-400 rounded-lg p-3 mt-4">
                  <p className="text-lg text-yellow-800 font-semibold">
                    🏆 New High Score! 🏆
                  </p>
                </div>
              )}
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-lg"
                onClick={resetGame}
              >
                🔄 Play Again
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default SimonSaysPage;

/**
 * Snake Game Page
 * Main container for the Snake game
 */

import React from 'react';
import { useSnakeGame } from '../../../hooks/useSnakeGame';
import { SnakeBoard } from './SnakeBoard';
import { SnakeControls } from './SnakeControls';
import type { Difficulty, GridSize } from './types';
import GameLayout from '../../shared/GameLayout';
import { getStatusColor } from '../../../utils/gameUtils';
import { useWinCelebration } from '../../../hooks/useWinCelebration';

interface SnakePageProps {
  onNavigateHome: () => void;
}

const SnakePage: React.FC<SnakePageProps> = ({ onNavigateHome }) => {
  const { gameState, config, controls } = useSnakeGame();

  useWinCelebration(
    gameState.gameStatus === 'gameOver',
    gameState.score === gameState.highScore && gameState.score > 0,
  );

  const getStatusMessage = (): string => {
    switch (gameState.gameStatus) {
      case 'ready':
        return 'Press any arrow key or tap a direction to start!';
      case 'playing':
        return 'Playing...';
      case 'paused':
        return 'Paused - Press Space or Pause button to resume';
      case 'gameOver':
        return 'Game Over! Press R or Play Again to restart';
      default:
        return '';
    }
  };

  return (
    <GameLayout
      title="Snake Game"
      emoji="🐍"
      onNavigateHome={onNavigateHome}
      bgColorClass="bg-gradient-to-b from-emerald-100 to-emerald-200"
      headerActions={
        <>
          {/* Speed buttons */}
          <div className="flex gap-1" title="Game Speed">
            {([['easy', '🐌', 'Slow'], ['medium', '🏃', 'Medium'], ['hard', '⚡', 'Fast']] as const).map(([val, icon, label]) => (
              <button
                key={val}
                aria-label={label}
                onClick={() => controls.setDifficulty(val as Difficulty)}
                disabled={gameState.gameStatus === 'playing'}
                className={`kid-button text-base md:text-lg px-2 md:px-3 py-1 md:py-2 ${gameState.difficulty === val ? '' : 'opacity-50'}`}
              >
                {icon}
              </button>
            ))}
          </div>

          {/* Grid size buttons */}
          <div className="flex gap-1" title="Grid Size">
            {([['small', '📐', 'Small 15×15'], ['medium', '📏', 'Medium 20×20'], ['large', '📊', 'Large 25×25'], ['xlarge', '🗺️', 'X-Large 30×30']] as const).map(([val, icon, label]) => (
              <button
                key={val}
                aria-label={label}
                onClick={() => controls.setGridSize(val as GridSize)}
                disabled={gameState.gameStatus === 'playing'}
                className={`kid-button text-base md:text-lg px-2 md:px-3 py-1 md:py-2 ${gameState.gridSize === val ? '' : 'opacity-50'}`}
              >
                {icon}
              </button>
            ))}
          </div>

          {(gameState.gameStatus === 'playing' || gameState.gameStatus === 'paused') && (
            <button
              className="kid-button text-xs md:text-sm bg-yellow-500 hover:bg-yellow-600 px-2 md:px-4 py-1 md:py-2"
              onClick={controls.togglePause}
            >
              {gameState.gameStatus === 'paused' ? '▶️' : '⏸️'}
              <span className="hidden md:inline ml-1">{gameState.gameStatus === 'paused' ? 'Resume' : 'Pause'}</span>
            </button>
          )}

          {gameState.gameStatus !== 'ready' && (
            <button
              className="kid-button text-xs md:text-sm bg-blue-500 hover:bg-blue-600 px-2 md:px-4 py-1 md:py-2"
              onClick={controls.resetGame}
            >
              🔄<span className="hidden md:inline ml-1">Play Again</span>
            </button>
          )}
        </>
      }
    >
      {/* Score Display - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-3 gap-2 md:gap-4">
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Score</p>
            <p className="text-xl md:text-3xl font-bold text-lime-600">{gameState.score}</p>
          </div>
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">High</p>
            <p className="text-xl md:text-3xl font-bold text-yellow-600">{gameState.highScore}</p>
          </div>
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Length</p>
            <p className="text-xl md:text-3xl font-bold text-blue-600">{gameState.snake.length}</p>
          </div>
        </div>
      </div>

      {/* Status Message - Smaller on mobile */}
      <div className="text-center mb-2 md:mb-4">
        <p className={`text-sm md:text-lg font-semibold ${getStatusColor(gameState.gameStatus)}`}>
          {getStatusMessage()}
        </p>
      </div>

      {/* Game Board */}
      <div className="mb-2 md:mb-4">
        <SnakeBoard gameState={gameState} config={config} />
      </div>

      {/* Mobile Controls */}
      <div className="md:hidden mb-2">
        <SnakeControls
          onDirectionChange={controls.changeDirection}
          disabled={gameState.gameStatus === 'gameOver' || gameState.gameStatus === 'paused'}
        />
      </div>

      {/* Instructions - Hidden on mobile */}
      <div className="kid-card max-w-4xl mx-auto hidden md:block">
        <h2 className="text-xl font-bold mb-3 text-center text-emerald-800">
          How to Play
        </h2>

        <div className="space-y-3">
          <div>
            <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
            <p className="text-slate-700">
              Eat the apples 🍎 to grow your snake and score points. Don't hit the walls or yourself!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⌨️ Keyboard Controls</h3>
            <ul className="text-slate-700 space-y-1">
              <li><strong>Arrow Keys</strong> or <strong>WASD</strong> - Move snake</li>
              <li><strong>Space</strong> - Pause/Resume</li>
              <li><strong>R</strong> - Restart (when game over)</li>
            </ul>
          </div>

          <div className="md:hidden">
            <h3 className="font-semibold text-lg mb-1">📱 Touch Controls</h3>
            <p className="text-slate-700">
              Tap the arrow buttons above to change direction
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">📊 Scoring</h3>
            <p className="text-slate-700">
              Each apple gives you <strong>+10 points</strong> and makes your snake longer!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⚙️ Game Settings</h3>
            <div className="text-slate-700 space-y-2">
              <div>
                <strong>Speed:</strong>
                <ul className="ml-4 mt-1 space-y-1">
                  <li>🐌 <strong>Slow</strong> - Relaxed pace (200ms)</li>
                  <li>🏃 Medium - Moderate speed (150ms)</li>
                  <li>⚡ <strong>Fast</strong> - Quick reflexes needed! (100ms)</li>
                </ul>
              </div>
              <div>
                <strong>Grid Size:</strong>
                <ul className="ml-4 mt-1 space-y-1">
                  <li>📐 <strong>Small</strong> - Cozy 15×15 grid</li>
                  <li>📏 Medium - Standard 20×20 grid</li>
                  <li>📊 <strong>Large</strong> - Spacious 25×25 grid</li>
                  <li>🗺️ <strong>X-Large</strong> - Huge 30×30 grid!</li>
                </ul>
              </div>
              <p className="text-sm italic">Mix and match speed and grid size for your perfect challenge!</p>
            </div>
          </div>
        </div>
      </div>

      {/* Game Over Modal Overlay */}
      {gameState.gameStatus === 'gameOver' && (
        <div className="fixed inset-0 bg-gradient-to-b from-emerald-50/90 to-emerald-100/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <h2 className="text-3xl font-bold text-red-600 mb-4">Game Over!</h2>

            <div className="mb-6">
              <p className="text-xl mb-2">Final Score</p>
              <p className="text-5xl font-bold text-lime-600 mb-4">{gameState.score}</p>

              {gameState.score === gameState.highScore && gameState.score > 0 && (
                <p className="text-lg text-yellow-600 font-semibold">
                  🎉 New High Score! 🎉
                </p>
              )}
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-lime-500 hover:bg-lime-600 text-lg"
                onClick={controls.resetGame}
              >
                🔄 Play Again
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default SnakePage;

/**
 * OnboardingOverlay tests (PR-5d)
 *
 * Covers acceptance criteria:
 *  1. Overlay renders when firstRunComplete=false in storage
 *  2. Click through all 4 steps → dismiss sets firstRunComplete=true
 *  3. Overlay NOT in DOM when firstRunComplete=true in storage
 */

import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';

// ── Mocks ─────────────────────────────────────────────────────────────────────

const { mockGet, mockSet } = vi.hoisted(() => ({
  mockGet: vi.fn(),
  mockSet: vi.fn(),
}));

vi.mock('../../utils/storage', () => ({
  get: mockGet,
  set: mockSet,
  remove: vi.fn(),
  migrate: vi.fn(),
}));

// ── SUT import ────────────────────────────────────────────────────────────────

import OnboardingOverlay from './OnboardingOverlay';

// ── Tests ─────────────────────────────────────────────────────────────────────

beforeEach(() => {
  vi.clearAllMocks();
});

describe('OnboardingOverlay — first-run visibility', () => {
  it('shows the overlay when firstRunComplete=false', () => {
    mockGet.mockReturnValue(false);

    render(<OnboardingOverlay />);

    expect(screen.getByRole('dialog')).toBeInTheDocument();
  });

  it('does NOT render when firstRunComplete=true', () => {
    mockGet.mockReturnValue(true);

    render(<OnboardingOverlay />);

    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });
});

describe('OnboardingOverlay — step navigation (PR-5d)', () => {
  it('advances through all 4 steps and dismisses on final step', () => {
    mockGet.mockReturnValue(false);

    render(<OnboardingOverlay />);

    // Step 1: shows emoji 🎮 and "Next →" button
    expect(screen.getByText('Pick a game!')).toBeInTheDocument();
    expect(screen.getByText('Next →')).toBeInTheDocument();

    fireEvent.click(screen.getByText('Next →')); // → step 2
    expect(screen.getByText('Tap to play!')).toBeInTheDocument();

    fireEvent.click(screen.getByText('Next →')); // → step 3
    expect(screen.getByText("Today's challenge!")).toBeInTheDocument();

    fireEvent.click(screen.getByText('Next →')); // → step 4
    expect(screen.getByText('Save your art!')).toBeInTheDocument();

    // Last step shows "Got it!" not "Next →"
    expect(screen.queryByText('Next →')).not.toBeInTheDocument();
    expect(screen.getByText('🎉 Got it!')).toBeInTheDocument();
  });

  it('sets firstRunComplete=true and removes overlay on final dismiss', () => {
    mockGet.mockReturnValue(false);

    render(<OnboardingOverlay />);

    // Click through steps 1–3
    fireEvent.click(screen.getByText('Next →'));
    fireEvent.click(screen.getByText('Next →'));
    fireEvent.click(screen.getByText('Next →'));

    // Dismiss on step 4
    fireEvent.click(screen.getByText('🎉 Got it!'));

    // Storage written
    expect(mockSet).toHaveBeenCalledWith('firstRunComplete', true);

    // Overlay gone from DOM
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });
});

