1	// Main game logic hook for Jelly Volleyball
2	
3	import { useState, useEffect, useCallback, useRef } from 'react';
4	import type { GameState, GameConfig, Controls } from '../components/Games/JellyVolleyball/types';
5	import {
6	  updatePlayer,
7	  updateBall,
8	  handleBallPlayerCollision,
9	  defaultPhysicsConfig,
10	} from '../components/Games/JellyVolleyball/physics';
11	import { calculateAIControls, defaultAIConfig } from '../components/Games/JellyVolleyball/ai';
12	
13	/**
14	 * Convert a raw client X coordinate to an in-game X coordinate,
15	 * accounting for CSS scaling of the canvas element.
16	 * Exported for unit testing.
17	 */
18	export function computeGameX(
19	  clientX: number,
20	  rectLeft: number,
21	  rectWidth: number,
22	  canvasWidth: number
23	): number {
24	  return (clientX - rectLeft) * (canvasWidth / rectWidth);
25	}
26	
27	function getDefaultConfig(): GameConfig {
28	  const courtWidth = Math.min(
29	    typeof window !== 'undefined' && window.innerWidth > 0
30	      ? window.innerWidth - 32
31	      : 800,
32	    800
33	  );
34	  const courtHeight = courtWidth / 2;
35	  return {
36	    courtWidth,
37	    courtHeight,
38	    netHeight: courtHeight / 4,
39	    playerRadius: 35,
40	    ballRadius: 32,
41	    gravity: 0.06,
42	    pointsToWin: 7,
43	  };
44	}
45	
46	// Initialize game state
47	function createInitialState(config: GameConfig): GameState {
48	  const player1StartX = config.courtWidth / 4;
49	  const player2StartX = (config.courtWidth * 3) / 4;
50	  const startY = config.courtHeight - config.playerRadius;
51	
52	  return {
53	    player1: {
54	      position: { x: player1StartX, y: startY },
55	      velocity: { x: 0, y: 0 },
56	      radius: config.playerRadius,
57	      mass: 1.0,
58	      wobbleOffset: { x: 0, y: 0 },
59	      wobbleVelocity: { x: 0, y: 0 },
60	      color: '#FF6B6B',
61	      isAI: false,
62	    },
63	    player2: {
64	      position: { x: player2StartX, y: startY },
65	      velocity: { x: 0, y: 0 },
66	      radius: config.playerRadius,
67	      mass: 1.0,
68	      wobbleOffset: { x: 0, y: 0 },
69	      wobbleVelocity: { x: 0, y: 0 },
70	      color: '#4ECDC4',
71	      isAI: true,
72	    },
73	    ball: {
74	      position: { x: config.courtWidth / 2, y: 60 }, // Higher start position
75	      velocity: { x: -1.0, y: 0 }, // Slower initial speed
76	      radius: config.ballRadius,
77	      mass: 0.5,
78	    },
79	    court: {
80	      width: config.courtWidth,
81	      height: config.courtHeight,
82	      netHeight: config.netHeight,
83	      netWidth: 8,
84	    },
85	    score: {
86	      player1: 0,
87	      player2: 0,
88	    },
89	    gameStatus: 'playing',
90	    winner: null,
91	    lastScorer: null,
92	    servingPlayer: 1,
93	  };
94	}
95	
96	// Reset ball position after scoring
97	function resetBall(state: GameState, servingPlayer: number): void {
98	  const startX = servingPlayer === 1 ? state.court.width / 4 : (state.court.width * 3) / 4;
99	
100	  state.ball.position.x = startX;
101	  state.ball.position.y = 80; // Much higher starting position for better reaction time
102	  state.ball.velocity.x = servingPlayer === 1 ? 1.0 : -1.0; // Slower serve speed
103	  state.ball.velocity.y = 0;
104	}
105	
106	// Reset player positions
107	function resetPlayers(state: GameState): void {
108	  const player1StartX = state.court.width / 4;
109	  const player2StartX = (state.court.width * 3) / 4;
110	  const startY = state.court.height - state.player1.radius;
111	
112	  state.player1.position.x = player1StartX;
113	  state.player1.position.y = startY;
114	  state.player1.velocity.x = 0;
115	  state.player1.velocity.y = 0;
116	
117	  state.player2.position.x = player2StartX;
118	  state.player2.position.y = startY;
119	  state.player2.velocity.x = 0;
120	  state.player2.velocity.y = 0;
121	}
122	
123	export function useJellyVolleyball(config: GameConfig = getDefaultConfig()) {
124	  const [gameState, setGameState] = useState<GameState>(() => createInitialState(config));
125	  const [isPaused, setIsPaused] = useState(false);
126	
127	  const player1ControlsRef = useRef<Controls>({ left: false, right: false, jump: false });
128	  const animationFrameRef = useRef<number>();
129	  const lastTimeRef = useRef<number>(Date.now());
130	  const scorePopupTimeoutRef = useRef<NodeJS.Timeout | null>(null);
131	
132	  // Mouse and touch control refs
133	  const mouseXRef = useRef<number | null>(null);
134	  const touchStartYRef = useRef<number | null>(null);
135	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
136	  // Cached bounding rect — updated on touchstart and window resize to avoid
137	  // calling getBoundingClientRect() on every touchmove event.
138	  const rectRef = useRef<DOMRect | null>(null);
139	
140	  // Game loop
141	  const gameLoop = useCallback(() => {
142	    if (isPaused) {
143	      animationFrameRef.current = requestAnimationFrame(gameLoop);
144	      return;
145	    }
146	
147	    const now = Date.now();
148	    const deltaTime = Math.min((now - lastTimeRef.current) / 16, 2); // Cap at 2x speed
149	    lastTimeRef.current = now;
150	
151	    setGameState((prevState: GameState) => {
152	      if (prevState.gameStatus !== 'playing') {
153	        return prevState;
154	      }
155	
156	      const newState = { ...prevState };
157	
158	      // Calculate AI controls for player 2
159	      const player2Controls = newState.player2.isAI
160	        ? calculateAIControls(newState.player2, newState.ball, newState.court, defaultAIConfig)
161	        : { left: false, right: false, jump: false };
162	
163	      // Apply mouse/touch controls to player 1 if mouse position is set
164	      const player1Controls = { ...player1ControlsRef.current };
165	      if (mouseXRef.current !== null) {
166	        const targetX = mouseXRef.current;
167	        const playerX = newState.player1.position.x;
168	        const threshold = 20; // Dead zone to prevent jittering
169	
170	        if (targetX < playerX - threshold) {
171	          player1Controls.left = true;
172	          player1Controls.right = false;
173	        } else if (targetX > playerX + threshold) {
174	          player1Controls.left = false;
175	          player1Controls.right = true;
176	        } else {
177	          player1Controls.left = false;
178	          player1Controls.right = false;
179	        }
180	      }
181	
182	      // Update players
183	      updatePlayer(
184	        newState.player1,
185	        newState.court,
186	        defaultPhysicsConfig,
187	        player1Controls,
188	        deltaTime,
189	        'left'
190	      );
191	      updatePlayer(
192	        newState.player2,
193	        newState.court,
194	        defaultPhysicsConfig,
195	        player2Controls,
196	        deltaTime,
197	        'right'
198	      );
199	
200	      // Update ball
201	      const { scored, scoringSide } = updateBall(
202	        newState.ball,
203	        newState.court,
204	        defaultPhysicsConfig,
205	        deltaTime
206	      );
207	
208	      // Handle ball-player collisions
209	      handleBallPlayerCollision(newState.ball, newState.player1, defaultPhysicsConfig);
210	      handleBallPlayerCollision(newState.ball, newState.player2, defaultPhysicsConfig);
211	
212	      // Handle scoring
213	      if (scored && scoringSide) {
214	        if (scoringSide === 'left') {
215	          // Ball landed on left side, player 2 scores
216	          newState.score.player2++;
217	          newState.lastScorer = 2;
218	          newState.servingPlayer = 1;
219	        } else {
220	          // Ball landed on right side, player 1 scores
221	          newState.score.player1++;
222	          newState.lastScorer = 1;
223	          newState.servingPlayer = 2;
224	        }
225	
226	        // Check for winner
227	        if (newState.score.player1 >= config.pointsToWin) {
228	          newState.gameStatus = 'gameOver';
229	          newState.winner = 1;
230	        } else if (newState.score.player2 >= config.pointsToWin) {
231	          newState.gameStatus = 'gameOver';
232	          newState.winner = 2;
233	        } else {
234	          // Reset for next point
235	          resetBall(newState, newState.servingPlayer);
236	          resetPlayers(newState);
237	        }
238	      }
239	
240	      return newState;
241	    });
242	
243	    animationFrameRef.current = requestAnimationFrame(gameLoop);
244	  }, [config.pointsToWin, isPaused]);
245	
246	  // Control functions for touch/button controls
247	  const setControl = useCallback((control: keyof Controls, value: boolean) => {
248	    player1ControlsRef.current[control] = value;
249	  }, []);
250	
251	  const resetGame = useCallback(() => {
252	    setGameState(createInitialState(config));
253	    player1ControlsRef.current = { left: false, right: false, jump: false };
254	    setIsPaused(false);
255	  }, [config]);
256	
257	  const togglePause = useCallback(() => {
258	    setIsPaused((prev: boolean) => !prev);
259	  }, []);
260	
261	  // Start game loop
262	  useEffect(() => {
263	    lastTimeRef.current = Date.now();
264	    animationFrameRef.current = requestAnimationFrame(gameLoop);
265	
266	    return () => {
267	      if (animationFrameRef.current) {
268	        cancelAnimationFrame(animationFrameRef.current);
269	      }
270	    };
271	  }, [gameLoop]);
272	
273	  // Keyboard controls
274	  useEffect(() => {
275	    const handleKeyDown = (e: KeyboardEvent) => {
276	      if (gameState.gameStatus === 'gameOver') {
277	        // Any key restarts the game
278	        resetGame();
279	        return;
280	      }
281	
282	      const key = e.key.toLowerCase();
283	
284	      if (key === 'arrowleft' || key === 'a') {
285	        player1ControlsRef.current.left = true;
286	        e.preventDefault();
287	      }
288	      if (key === 'arrowright' || key === 'd') {
289	        player1ControlsRef.current.right = true;
290	        e.preventDefault();
291	      }
292	      if (key === 'arrowup' || key === 'w' || key === ' ') {
293	        player1ControlsRef.current.jump = true;
294	        e.preventDefault();
295	      }
296	      if (key === 'escape') {
297	        setIsPaused((prev: boolean) => !prev);
298	      }
299	    };
300	
301	    const handleKeyUp = (e: KeyboardEvent) => {
302	      const key = e.key.toLowerCase();
303	
304	      if (key === 'arrowleft' || key === 'a') {
305	        player1ControlsRef.current.left = false;
306	      }
307	      if (key === 'arrowright' || key === 'd') {
308	        player1ControlsRef.current.right = false;
309	      }
310	      if (key === 'arrowup' || key === 'w' || key === ' ') {
311	        player1ControlsRef.current.jump = false;
312	      }
313	    };
314	
315	    window.addEventListener('keydown', handleKeyDown);
316	    window.addEventListener('keyup', handleKeyUp);
317	
318	    return () => {
319	      window.removeEventListener('keydown', handleKeyDown);
320	      window.removeEventListener('keyup', handleKeyUp);
321	    };
322	  }, [gameState.gameStatus, resetGame]);
323	
324	  // Mouse and touch controls
325	  useEffect(() => {
326	    const canvas = canvasRef.current;
327	    if (!canvas) return;
328	
329	    const handleMouseMove = (e: MouseEvent) => {
330	      if (!canvas) return;
331	      const rect = canvas.getBoundingClientRect();
332	      const scaleX = gameState.court.width / rect.width;
333	      mouseXRef.current = (e.clientX - rect.left) * scaleX;
334	    };
335	
336	    const handleMouseDown = (e: MouseEvent) => {
337	      if (e.button === 2) { // Right click
338	        e.preventDefault();
339	        player1ControlsRef.current.jump = true;
340	        setTimeout(() => {
341	          player1ControlsRef.current.jump = false;
342	        }, 100);
343	      }
344	    };
345	
346	    const handleContextMenu = (e: MouseEvent) => {
347	      e.preventDefault(); // Prevent context menu on right-click
348	    };
349	
350	    const handleTouchStart = (e: TouchEvent) => {
351	      if (!canvas || e.touches.length === 0) return;
352	      const touch = e.touches[0];
353	      // Cache rect on touchstart — avoids getBoundingClientRect per touchmove.
354	      rectRef.current = canvas.getBoundingClientRect();
355	      mouseXRef.current = computeGameX(touch.clientX, rectRef.current.left, rectRef.current.width, canvas.width);
356	      touchStartYRef.current = touch.clientY;
357	    };
358	
359	    const handleTouchMove = (e: TouchEvent) => {
360	      if (!canvas || e.touches.length === 0) return;
361	      e.preventDefault();
362	      const touch = e.touches[0];
363	      // Use cached rect; fall back to live query only if cache is empty.
364	      const rect = rectRef.current ?? canvas.getBoundingClientRect();
365	      mouseXRef.current = computeGameX(touch.clientX, rect.left, rect.width, canvas.width);
366	
367	      // Check for upward drag to jump
368	      if (touchStartYRef.current !== null) {
369	        const dragDistance = touchStartYRef.current - touch.clientY;
370	        if (dragDistance > 30) { // Drag up at least 30px to jump
371	          player1ControlsRef.current.jump = true;
372	          touchStartYRef.current = touch.clientY; // Reset to prevent continuous jumping
373	        }
374	      }
375	    };
376	
377	    const handleTouchEnd = () => {
378	      player1ControlsRef.current.jump = false;
379	      touchStartYRef.current = null;
380	    };
381	
382	    // Invalidate cached rect when the viewport resizes (canvas CSS size may change).
383	    const handleResize = () => {
384	      rectRef.current = canvas.getBoundingClientRect();
385	    };
386	
387	    // Add event listeners
388	    canvas.addEventListener('mousemove', handleMouseMove);
389	    canvas.addEventListener('mousedown', handleMouseDown);
390	    canvas.addEventListener('contextmenu', handleContextMenu);
391	    canvas.addEventListener('touchstart', handleTouchStart);
392	    canvas.addEventListener('touchmove', handleTouchMove, { passive: false });
393	    canvas.addEventListener('touchend', handleTouchEnd);
394	    window.addEventListener('resize', handleResize);
395	
396	    return () => {
397	      canvas.removeEventListener('mousemove', handleMouseMove);
398	      canvas.removeEventListener('mousedown', handleMouseDown);
399	      canvas.removeEventListener('contextmenu', handleContextMenu);
400	      canvas.removeEventListener('touchstart', handleTouchStart);
401	      canvas.removeEventListener('touchmove', handleTouchMove);
402	      canvas.removeEventListener('touchend', handleTouchEnd);
403	      window.removeEventListener('resize', handleResize);
404	    };
405	  }, [gameState.court.width]);
406	
407	  // Clear score popup after 2 seconds
408	  useEffect(() => {
409	    if (gameState.lastScorer !== null) {
410	      // Clear any existing timeout
411	      if (scorePopupTimeoutRef.current) {
412	        clearTimeout(scorePopupTimeoutRef.current);
413	      }
414	
415	      // Set timeout to clear the popup after 2 seconds
416	      scorePopupTimeoutRef.current = setTimeout(() => {
417	        setGameState((prev) => ({
418	          ...prev,
419	          lastScorer: null,
420	        }));
421	        scorePopupTimeoutRef.current = null;
422	      }, 2000);
423	    }
424	
425	    return () => {
426	      if (scorePopupTimeoutRef.current) {
427	        clearTimeout(scorePopupTimeoutRef.current);
428	      }
429	    };
