1	/**
2	 * Snake Game Hook
3	 * Core game logic and state management
4	 */
5	
6	import { useState, useEffect, useRef, useCallback } from 'react';
7	import type {
8	  Position,
9	  Direction,
10	  GameState,
11	  Difficulty,
12	  GridSize,
13	  SnakeControls,
14	  SnakeConfig,
15	} from '../components/Games/Snake/types';
16	import { buildSnakeConfig } from '../components/Games/Snake/types';
17	import * as storage from '../utils/storage';
18	
19	const HIGH_SCORE_KEY = 'snakeHighScore';
20	
21	// Direction vectors
22	const DIRECTION_VECTORS: Record<Direction, Position> = {
23	  up: { x: 0, y: -1 },
24	  down: { x: 0, y: 1 },
25	  left: { x: -1, y: 0 },
26	  right: { x: 1, y: 0 },
27	};
28	
29	// Opposite directions (to prevent 180° turns)
30	const OPPOSITE_DIRECTIONS: Record<Direction, Direction> = {
31	  up: 'down',
32	  down: 'up',
33	  left: 'right',
34	  right: 'left',
35	};
36	
37	/**
38	 * Get high score from storage.
39	 */
40	const getHighScore = (): number => {
41	  return storage.get(HIGH_SCORE_KEY, 0);
42	};
43	
44	/**
45	 * Save high score to storage.
46	 */
47	const saveHighScore = (score: number): void => {
48	  storage.set(HIGH_SCORE_KEY, score);
49	};
50	
51	/**
52	 * Initialize snake at center of grid
53	 */
54	const initializeSnake = (config: SnakeConfig): Position[] => {
55	  const centerX = Math.floor(config.gridWidth / 2);
56	  const centerY = Math.floor(config.gridHeight / 2);
57	
58	  const snake: Position[] = [];
59	  for (let i = 0; i < config.initialLength; i++) {
60	    snake.push({ x: centerX - i, y: centerY });
61	  }
62	  return snake;
63	};
64	
65	/**
66	 * Spawn food at random position not occupied by snake
67	 */
68	const spawnFood = (snake: Position[], config: SnakeConfig): Position => {
69	  let attempts = 0;
70	  const maxAttempts = 100;
71	
72	  while (attempts < maxAttempts) {
73	    const food: Position = {
74	      x: Math.floor(Math.random() * config.gridWidth),
75	      y: Math.floor(Math.random() * config.gridHeight),
76	    };
77	
78	    // Check if food overlaps with snake
79	    const overlaps = snake.some(segment =>
80	      segment.x === food.x && segment.y === food.y
81	    );
82	
83	    if (!overlaps) {
84	      return food;
85	    }
86	
87	    attempts++;
88	  }
89	
90	  // Fallback: return top-left corner (should never happen)
91	  return { x: 0, y: 0 };
92	};
93	
94	/**
95	 * Initialize game state
96	 */
97	const initializeGameState = (difficulty: Difficulty, gridSize: GridSize): GameState => {
98	  const config = buildSnakeConfig(difficulty, gridSize);
99	  const snake = initializeSnake(config);
100	  const food = spawnFood(snake, config);
101	  const highScore = getHighScore();
102	
103	  return {
104	    snake,
105	    food,
106	    direction: 'right',
107	    nextDirection: 'right',
108	    score: 0,
109	    highScore,
110	    gameStatus: 'ready',
111	    difficulty,
112	    gridSize,
113	  };
114	};
115	
116	export const useSnakeGame = () => {
117	  const [difficulty, setDifficulty] = useState<Difficulty>('easy');
118	  const [gridSize, setGridSize] = useState<GridSize>('medium');
119	  const [gameState, setGameState] = useState<GameState>(() =>
120	    initializeGameState(difficulty, gridSize)
121	  );
122	
123	  const gameLoopRef = useRef<number | null>(null);
124	  const nextDirectionRef = useRef<Direction>('right');
125	
126	  /**
127	   * Get current config based on difficulty and grid size
128	   */
129	  const config: SnakeConfig = buildSnakeConfig(gameState.difficulty, gameState.gridSize);
130	
131	  /**
132	   * Check if two positions are equal
133	   */
134	  const positionsEqual = (p1: Position, p2: Position): boolean => {
135	    return p1.x === p2.x && p1.y === p2.y;
136	  };
137	
138	  /**
139	   * Check wall collision
140	   */
141	  const checkWallCollision = useCallback((head: Position): boolean => {
142	    return (
143	      head.x < 0 ||
144	      head.x >= config.gridWidth ||
145	      head.y < 0 ||
146	      head.y >= config.gridHeight
147	    );
148	  }, [config]);
149	
150	  /**
151	   * Check self collision
152	   */
153	  const checkSelfCollision = useCallback((head: Position, snake: Position[]): boolean => {
154	    return snake.some(segment => positionsEqual(segment, head));
155	  }, []);
156	
157	  /**
158	   * Game tick - move snake and update state
159	   */
160	  const gameTick = useCallback(() => {
161	    setGameState((prevState: GameState) => {
162	      if (prevState.gameStatus !== 'playing') {
163	        return prevState;
164	      }
165	
166	      const { snake, food, score, highScore } = prevState;
167	      const direction = nextDirectionRef.current;
168	
169	      // Calculate new head position
170	      const currentHead = snake[0];
171	      const vector: Position = DIRECTION_VECTORS[direction];
172	      const newHead: Position = {
173	        x: currentHead.x + vector.x,
174	        y: currentHead.y + vector.y,
175	      };
176	
177	      // Check wall collision
178	      if (checkWallCollision(newHead)) {
179	        const finalHighScore = Math.max(score, highScore);
180	        saveHighScore(finalHighScore);
181	        return {
182	          ...prevState,
183	          gameStatus: 'gameOver',
184	          highScore: finalHighScore,
185	        };
186	      }
187	
188	      // Check self collision
189	      if (checkSelfCollision(newHead, snake)) {
190	        const finalHighScore = Math.max(score, highScore);
191	        saveHighScore(finalHighScore);
192	        return {
193	          ...prevState,
194	          gameStatus: 'gameOver',
195	          highScore: finalHighScore,
196	        };
197	      }
198	
199	      // Check food collision
200	      const ateFood = positionsEqual(newHead, food);
201	      let newSnake: Position[];
202	      let newFood = food;
203	      let newScore = score;
204	
205	      if (ateFood) {
206	        // Grow snake (don't remove tail)
207	        newSnake = [newHead, ...snake];
208	        newFood = spawnFood(newSnake, config);
209	        newScore = score + 10;
210	      } else {
211	        // Move snake (remove tail)
212	        newSnake = [newHead, ...snake.slice(0, -1)];
213	      }
214	
215	      return {
216	        ...prevState,
217	        snake: newSnake,
218	        food: newFood,
219	        direction,
220	        score: newScore,
221	        highScore: Math.max(newScore, highScore),
222	      };
223	    });
224	  }, [config, checkWallCollision, checkSelfCollision]);
225	
226	  /**
227	   * Start game loop
228	   */
229	  const startGameLoop = useCallback(() => {
230	    if (gameLoopRef.current !== null) {
231	      clearInterval(gameLoopRef.current);
232	    }
233	
234	    gameLoopRef.current = window.setInterval(() => {
235	      gameTick();
236	    }, config.tickMs);
237	  }, [gameTick, config.tickMs]);
238	
239	  /**
240	   * Stop game loop
241	   */
242	  const stopGameLoop = useCallback(() => {
243	    if (gameLoopRef.current !== null) {
244	      clearInterval(gameLoopRef.current);
245	      gameLoopRef.current = null;
246	    }
247	  }, []);
248	
249	  /**
250	   * Change direction (with validation)
251	   */
252	  const changeDirection = useCallback((newDirection: Direction) => {
253	    setGameState((prevState: GameState) => {
254	      // Don't allow direction change if game is not playing or ready
255	      if (prevState.gameStatus !== 'playing' && prevState.gameStatus !== 'ready') {
256	        return prevState;
257	      }
258	
259	      // Start game if in ready state
260	      if (prevState.gameStatus === 'ready') {
261	        nextDirectionRef.current = newDirection;
262	        return {
263	          ...prevState,
264	          direction: newDirection,
265	          nextDirection: newDirection,
266	          gameStatus: 'playing' as const,
267	        };
268	      }
269	
270	      // Prevent 180° turns
271	      const currentDirection = nextDirectionRef.current;
272	      const oppositeDirection: Direction = OPPOSITE_DIRECTIONS[currentDirection];
273	      if (oppositeDirection === newDirection) {
274	        return prevState;
275	      }
276	
277	      // Buffer the direction change
278	      nextDirectionRef.current = newDirection;
279	
280	      return {
281	        ...prevState,
282	        nextDirection: newDirection,
283	      };
284	    });
285	  }, []);
286	
287	  /**
288	   * Toggle pause
289	   */
290	  const togglePause = useCallback(() => {
291	    setGameState((prevState: GameState) => {
292	      if (prevState.gameStatus === 'playing') {
293	        return { ...prevState, gameStatus: 'paused' as const };
294	      } else if (prevState.gameStatus === 'paused') {
295	        return { ...prevState, gameStatus: 'playing' as const };
296	      }
297	      return prevState;
298	    });
299	  }, []);
300	
301	  /**
302	   * Reset game
303	   */
304	  const resetGame = useCallback(() => {
305	    stopGameLoop();
306	    const newState = initializeGameState(gameState.difficulty, gameState.gridSize);
307	    nextDirectionRef.current = 'right';
308	    setGameState(newState);
309	  }, [stopGameLoop, gameState.difficulty, gameState.gridSize]);
310	
311	  /**
312	   * Change difficulty (resets game, keeps grid size)
313	   */
314	  const changeDifficulty = useCallback((newDifficulty: Difficulty) => {
315	    stopGameLoop();
316	    const newState = initializeGameState(newDifficulty, gameState.gridSize);
317	    nextDirectionRef.current = 'right';
318	    setGameState(newState);
319	    setDifficulty(newDifficulty);
