/**
 * Drawing Challenge Game Page
 * Shows prompts and integrates with drawing canvas
 */

import React, { useState, useCallback, useRef } from 'react';
import { useDrawingChallenge } from '../../../hooks/useDrawingChallenge';
import GameLayout from '../../shared/GameLayout';
import DrawingCanvasWithTools from '../../Canvas/DrawingCanvasWithTools';
import type { Category, GameMode } from './types';
import { categoryNames } from './prompts';
import { formatTime } from '../../../utils/gameUtils';

interface DrawingChallengePageProps {
  onNavigateHome: () => void;
}

const DrawingChallengePage: React.FC<DrawingChallengePageProps> = ({ onNavigateHome }) => {
  const {
    gameState,
    daily,
    startChallenge,
    finishChallenge,
    nextPrompt,
    setCategory,
    setMode,
    setTimeLimit
  } = useDrawingChallenge();

  const {
    currentPrompt,
    gameStatus,
    mode,
    category,
    timeLimit,
    timeRemaining,
    completedChallenges
  } = gameState;

  const [showCanvas, setShowCanvas] = useState(false);
  const clearCanvasRef = useRef<(() => void) | null>(null);

  const handleStartDrawing = useCallback(() => {
    startChallenge();
    setShowCanvas(true);
  }, [startChallenge]);

  const handleFinish = useCallback(() => {
    finishChallenge();
    setShowCanvas(false);
  }, [finishChallenge]);

  const handleNextPrompt = useCallback(() => {
    nextPrompt();
    setShowCanvas(false);
    if (clearCanvasRef.current) {
      clearCanvasRef.current();
    }
  }, [nextPrompt]);

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setCategory(e.target.value as Category);
    setShowCanvas(false);
  };

  const handleModeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setMode(e.target.value as GameMode);
    setShowCanvas(false);
  };

  const handleTimeLimitChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setTimeLimit(parseInt(e.target.value, 10));
  };

  const handleClearCanvas = useCallback(() => {
    if (clearCanvasRef.current) {
      clearCanvasRef.current();
    }
  }, []);

  const headerActions = (
    <>
      {/* Category Selector - Compact on mobile */}
      <select
        value={category}
        onChange={handleCategoryChange}
        disabled={gameStatus === 'drawing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Drawing Category"
      >
        {Object.entries(categoryNames).map(([key, name]) => (
          <option key={key} value={key}>
            {name}
          </option>
        ))}
      </select>

      {/* Mode Selector - Compact on mobile */}
      <select
        value={mode}
        onChange={handleModeChange}
        disabled={gameStatus === 'drawing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Game Mode"
      >
        <option value="free">✨ Free</option>
        <option value="timed">⏱️ Timed</option>
      </select>

      {/* Time Limit Selector (only in timed mode) - Compact on mobile */}
      {mode === 'timed' && (
        <select
          value={timeLimit}
          onChange={handleTimeLimitChange}
          disabled={gameStatus === 'drawing'}
          className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
          title="Time Limit"
        >
          <option value={60}>1m</option>
          <option value={120}>2m</option>
          <option value={180}>3m</option>
          <option value={300}>5m</option>
        </select>
      )}
    </>
  );

  return (
    <GameLayout
      title="Drawing Challenge"
      emoji="🎨"
      onNavigateHome={onNavigateHome}
      headerActions={headerActions}
      bgColorClass="bg-gradient-to-b from-purple-100 to-pink-100"
    >
      {/* Daily Challenge Banner */}
      {!showCanvas && (
        <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-3 md:p-5 bg-gradient-to-r from-yellow-100 to-orange-100 border-2 border-yellow-300">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div>
              <p className="text-xs md:text-sm font-bold text-yellow-700 uppercase tracking-wide mb-1">
                🌟 Today's Challenge
              </p>
              <p className="text-lg md:text-2xl font-bold text-orange-700">
                {daily.dailyPrompt.emoji} Draw a {daily.dailyPrompt.text}!
              </p>
            </div>
            <div className="text-center">
              {daily.streak > 0 ? (
                <>
                  <p className="text-2xl md:text-3xl font-bold text-orange-500">
                    🔥 Day {daily.streak}
                  </p>
                  <p className="text-xs text-orange-600 font-semibold">streak!</p>
                </>
              ) : (
                <p className="text-sm font-semibold text-yellow-700">
                  Start your streak today!
                </p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Stats Panel - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-2 md:grid-cols-3 gap-2 md:gap-4">
          {/* Challenges Completed */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Completed</p>
            <p className="text-xl md:text-3xl font-bold text-green-600">
              {completedChallenges.length}
            </p>
          </div>

          {/* Current Difficulty */}
          {currentPrompt && (
            <div className="text-center">
              <p className="text-xs md:text-sm text-slate-600 font-semibold">Difficulty</p>
              <p className="text-xl md:text-3xl font-bold text-purple-600">
                {currentPrompt.difficulty === 1 ? '⭐' : currentPrompt.difficulty === 2 ? '⭐⭐' : '⭐⭐⭐'}
              </p>
            </div>
          )}

          {/* Timer (timed mode only) */}
          {mode === 'timed' && gameStatus === 'drawing' && (
            <div className="text-center">
              <p className="text-xs md:text-sm text-slate-600 font-semibold">Time Left</p>
              <p className={`text-xl md:text-3xl font-bold ${timeRemaining < 30 ? 'text-red-600' : 'text-blue-600'}`}>
                {formatTime(timeRemaining)}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Prompt Display (when not drawing) - Compact on mobile */}
      {!showCanvas && currentPrompt && (
        <div className="max-w-2xl mx-auto mb-2 md:mb-6">
          <div className="kid-card text-center bg-white p-4 md:p-8">
            <div className="text-5xl md:text-8xl mb-2 md:mb-4 animate-bounce-once">
              {currentPrompt.emoji}
            </div>
            <h2 className="text-2xl md:text-4xl font-bold text-purple-700 mb-2">
              Draw a {currentPrompt.text}!
            </h2>
            <p className="text-sm md:text-lg text-slate-600 mb-4 md:mb-6">
              {mode === 'timed'
                ? `You have ${formatTime(timeLimit)} to draw it!`
                : 'Take your time and be creative!'}
            </p>

            <div className="flex gap-2 md:gap-3 justify-center flex-wrap">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-base md:text-xl px-4 md:px-8"
                onClick={handleStartDrawing}
              >
                🖌️ Start Drawing!
              </button>

              {gameStatus !== 'drawing' && (
                <button
                  className="kid-button bg-blue-500 hover:bg-blue-600 text-base md:text-xl px-4 md:px-8"
                  onClick={handleNextPrompt}
                >
                  🎲 Different Prompt
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Drawing Canvas (when drawing) */}
      {showCanvas && currentPrompt && (
        <div className="max-w-4xl mx-auto">
          {/* Prompt reminder */}
          <div className="kid-card bg-white p-4 mb-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-4xl">{currentPrompt.emoji}</span>
              <div>
                <p className="text-sm text-slate-600">Drawing:</p>
                <p className="text-2xl font-bold text-purple-700">
                  {currentPrompt.text}
                </p>
              </div>
            </div>

            {mode === 'timed' && (
              <div className="text-right">
                <p className="text-sm text-slate-600">Time Left</p>
                <p className={`text-3xl font-bold ${timeRemaining < 30 ? 'text-red-600 animate-pulse' : 'text-blue-600'}`}>
                  {formatTime(timeRemaining)}
                </p>
              </div>
            )}
          </div>

          {/* Canvas */}
          <div className="kid-card bg-white p-4 mb-4">
            <DrawingCanvasWithTools
              width={600}
              height={450}
              onDrawingChange={() => {
                // Could save drawing here if needed
                console.log('Drawing updated');
              }}
              clearCanvasRef={clearCanvasRef}
            />
          </div>

          {/* Drawing Controls */}
          <div className="flex gap-3 justify-center flex-wrap">
            <button
              className="kid-button bg-green-500 hover:bg-green-600 text-lg px-6"
              onClick={handleFinish}
            >
              ✅ I'm Done!
            </button>

            <button
              className="kid-button bg-orange-500 hover:bg-orange-600 text-lg px-6"
              onClick={handleClearCanvas}
            >
              🗑️ Clear Canvas
            </button>

            <button
