/**
 * GameLayout Component
 * Shared layout wrapper for all games
 * Provides consistent header, navigation, and styling
 */

import React, { useState } from 'react';
import { useSoundSetting } from '../../hooks/useSoundSetting';

interface GameLayoutProps {
  title: string;
  emoji: string;
  onNavigateHome: () => void;
  children: React.ReactNode;
  headerActions?: React.ReactNode;
  bgColorClass?: string;
  /**
   * Optional "How to Play" content.
   * • On ≥md screens it is rendered inline below the game (always visible).
   * • On mobile a ⓘ button appears in the header; tapping it opens a slide-up
   *   modal so the instructions don't eat precious game space.
   */
  instructions?: React.ReactNode;
}

const GameLayout: React.FC<GameLayoutProps> = ({
  title,
  emoji,
  onNavigateHome,
  children,
  headerActions,
  bgColorClass = 'bg-gradient-to-b from-blue-100 to-blue-200',
  instructions,
}) => {
  const { soundEnabled, toggleSound } = useSoundSetting();
  const [showInstructions, setShowInstructions] = useState(false);

  return (
    <div className={`min-h-screen ${bgColorClass} p-2 md:p-4`}>
      {/* Header - Mobile First */}
      <div className="flex items-center justify-between mb-2 md:mb-4 gap-2">
        {/* Title - Compact on mobile */}
        <h1 className="text-xl md:text-3xl font-bold text-gray-800 flex items-center gap-1 md:gap-2">
          <span className="text-2xl md:text-3xl">{emoji}</span>
          <span className="hidden sm:inline">{title}</span>
        </h1>

        {/* Actions and Home Button - Compact on mobile */}
        <div className="flex gap-1 md:gap-2 flex-wrap items-center justify-end">
          {headerActions}

          {/* ⓘ How-to-play — only visible on mobile; desktop sees instructions inline */}
          {instructions && (
            <button
              className="kid-button md:hidden text-xs px-2 py-1"
              onClick={() => setShowInstructions(true)}
              aria-label="How to Play"
            >
              ⓘ
            </button>
          )}

          <button
            className="kid-button text-xs md:text-sm px-2 md:px-4 py-1 md:py-2"
            onClick={toggleSound}
            aria-label={soundEnabled ? 'Mute sounds' : 'Unmute sounds'}
          >
            {soundEnabled ? '🔊' : '🔇'}
          </button>

          <button
            className="kid-button text-xs md:text-sm bg-slate-500 hover:bg-slate-600 px-2 md:px-4 py-1 md:py-2"
            onClick={onNavigateHome}
            aria-label="← Home"
          >
            <span className="md:hidden" aria-hidden="true">←</span>
            <span className="hidden md:inline" aria-hidden="true">← Home</span>
          </button>
        </div>
      </div>

      {/* Game Content - Maximum space on mobile */}
      <div className="game-content">
        {children}
      </div>

      {/* Instructions — inline on desktop, slide-up modal on mobile */}
      {instructions && (
        <>
          {/* Desktop: always rendered below game content */}
          <div className="kid-card max-w-4xl mx-auto hidden md:block mt-4">
            <h2 className="text-xl font-bold mb-3 text-center text-gray-800">How to Play</h2>
            {instructions}
          </div>

          {/* Mobile: shown only when ⓘ is tapped */}
          {showInstructions && (
            <div
              className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-end justify-center z-50 p-4"
              role="dialog"
              aria-modal="true"
              aria-label="How to Play"
              onClick={() => setShowInstructions(false)}
            >
              <div
                className="kid-card w-full max-w-lg max-h-[75vh] overflow-y-auto"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="flex items-center justify-between mb-3">
                  <h2 className="text-xl font-bold text-gray-800">How to Play</h2>
                  <button
                    className="kid-button text-sm px-3 py-1 bg-slate-500 hover:bg-slate-600"
                    onClick={() => setShowInstructions(false)}
                    aria-label="Close instructions"
                  >
                    ✕
                  </button>
                </div>
                {instructions}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default GameLayout;

import React, { useEffect, useMemo } from 'react';
import { useTetrisGame } from '../../../hooks/useTetrisGame';
import type { TetrisConfig, Cell } from './types';

interface Props {
  config: TetrisConfig;
}

const typeColor: Record<string, string> = {
  I: 'bg-cyan-400',
  O: 'bg-yellow-400',
  T: 'bg-purple-400',
  S: 'bg-green-400',
  Z: 'bg-red-400',
  J: 'bg-blue-400',
  L: 'bg-orange-400',
};

// Wrapped in React.memo with a structural comparator so only the ~5 cells that
// actually change on each 800ms tick re-render, not all 200.
const CellView = React.memo(
  function CellView({ cell }: { cell: Cell }) {
    if (!cell) return <div className="border border-white/20 bg-white/5" style={{ aspectRatio: '1 / 1' }} />;
    const color = typeColor[cell.type] ?? 'bg-gray-400';
    const glow = cell.locked ? 'shadow-inner' : 'shadow-lg';
    return (
      <div
        className={`${color} ${glow} rounded-sm border border-black/10`}
        style={{ aspectRatio: '1 / 1' }}
      />
    );
  },
  (prev, next) =>
    prev.cell === next.cell ||
    (prev.cell?.type === next.cell?.type && prev.cell?.locked === next.cell?.locked),
);

export default function TetrisBoard({ config }: Props) {
  const { state, board, controls } = useTetrisGame(config);

  const width = useMemo(() => board[0]?.length ?? config.width, [board, config.width]);

  useEffect(() => {
    const isTextInput = (el: Element | null): boolean => {
      if (!el) return false;
      const tag = (el as HTMLElement).tagName;
      const editable = (el as HTMLElement).getAttribute?.('contenteditable');
      return tag === 'INPUT' || tag === 'TEXTAREA' || editable === 'true';
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (isTextInput(document.activeElement)) return;
      switch (e.code) {
        case 'ArrowLeft':
          e.preventDefault();
          controls.moveLeft();
          break;
        case 'ArrowRight':
          e.preventDefault();
          controls.moveRight();
          break;
        case 'ArrowDown':
          e.preventDefault();
          controls.softDrop();
          break;
        case 'Space':
          e.preventDefault();
          controls.rotate();
          break;
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [controls]);

  return (
    <div className="w-full max-w-md mx-auto">
      <div className="flex items-center justify-between mb-3">
        <div className="text-sm">
          <div>Score: <span className="font-bold">{state.score}</span></div>
          <div>Level: <span className="font-bold">{state.level}</span></div>
          <div>Lines: <span className="font-bold">{state.lines}</span></div>
        </div>
        <div className="flex gap-2">
          <button className="kid-button px-3 py-1" onClick={() => controls.pause()}>Pause</button>
          <button className="kid-button px-3 py-1" onClick={() => controls.resume()}>Resume</button>
          <button className="kid-button px-3 py-1" onClick={() => controls.reset()}>Reset</button>
        </div>
      </div>

      <div className="bg-slate-800 rounded-lg p-2 border-4 border-slate-700">
        <div
          className="grid gap-0.5"
          style={{
            gridTemplateColumns: `repeat(${width}, minmax(0, 1fr))`,
          }}
        >
          {board.map((row, rIdx) => (
            <React.Fragment key={rIdx}>
              {row.map((c, cIdx) => (
                <CellView key={`${rIdx}-${cIdx}`} cell={c} />
              ))}
            </React.Fragment>
          ))}
        </div>
      </div>

      {state.gameOver && (
        <div className="mt-3 text-center text-red-600 font-bold">Game Over</div>
      )}

      <div className="mt-4 grid grid-cols-3 gap-3 select-none">
        <button className="kid-button text-xl py-3" onClick={controls.moveLeft}>◀️</button>
        <button className="kid-button text-xl py-3" onClick={controls.rotate}>🔄</button>
        <button className="kid-button text-xl py-3" onClick={controls.moveRight}>▶️</button>
        <div className="col-span-3">
          <button className="kid-button w-full text-xl py-3" onClick={controls.softDrop}>⬇️</button>
        </div>
      </div>

      <div className="mt-4 text-xs text-center text-gray-500">
        Tip: Use buttons for touch. Width/Height configurable in Tetris page.
      </div>
    </div>
  );
}

import '@testing-library/jest-dom/vitest';

// Hand-rolled localStorage stub — jsdom omits it; required by ShapeSorting (11) + ColorBlocks (3)
const _store: Record<string, string> = {};
const localStorageMock = {
  getItem: (key: string): string | null => _store[key] ?? null,
  setItem: (key: string, value: string): void => { _store[key] = String(value); },
  removeItem: (key: string): void => { delete _store[key]; },
  clear: (): void => { Object.keys(_store).forEach(k => delete _store[k]); },
  key: (index: number): string | null => Object.keys(_store)[index] ?? null,
  get length(): number { return Object.keys(_store).length; },
};
Object.defineProperty(globalThis, 'localStorage', { value: localStorageMock, writable: true });

// jsdom does not implement window.matchMedia — stub it so hooks that check
// prefers-reduced-motion don't throw in the test environment.
// Default: matches=false (motion allowed), which preserves existing test expectations.
Object.defineProperty(globalThis, 'matchMedia', {
  writable: true,
  value: (query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: () => {},
    removeListener: () => {},
    addEventListener: () => {},
    removeEventListener: () => {},
    dispatchEvent: () => false,
  }),
});

/**
 * Pop the Balloons Game Hook
 * Manages game state and logic for Pop the Balloons
 * Refactored from 12 useState calls to a single useReducer (PR-4c1)
 */

import { useReducer, useEffect, useCallback, useRef } from 'react';
import type {
  PopBalloonsState,
  Balloon,
  BalloonType,
  Difficulty,
  GridSize,
} from '../components/Games/PopBalloons/types';
import {
  difficultySettings,
  gridSizeSettings,
  POINTS,
  balloonColors,
  COMBO_WINDOW,
} from '../components/Games/PopBalloons/constants';
import { saveHighScore, getHighScore, playSound, randomChoice } from '../utils/gameUtils';

const GAME_KEY = 'popBalloons';

// Internal state — superset of public PopBalloonsState; adds lastPopTime for combo timing
interface InternalState extends PopBalloonsState {
  lastPopTime: number;
}

// Discriminated union of all state transitions
export type BalloonAction =
  | { type: 'RESET'; difficulty: Difficulty; gridSize: GridSize; highScore: number }
  | { type: 'START' }
  | { type: 'SET_DIFFICULTY'; difficulty: Difficulty }
  | { type: 'SET_GRID_SIZE'; gridSize: GridSize }
  | { type: 'SPAWN_BALLOON'; balloon: Balloon }
  | { type: 'POP_BALLOON'; balloonId: string; now: number }
  | { type: 'EXPIRE_BALLOON'; balloonId: string }
  | { type: 'TICK' }
  | { type: 'LOAD_HIGH_SCORE'; highScore: number };

export function makeInitialState(
  difficulty: Difficulty,
  gridSize: GridSize = 'small',
  highScore = 0,
): InternalState {
  const settings = difficultySettings[difficulty];
  return {
    difficulty,
    gridSize,
    balloons: [],
    score: 0,
    highScore,
    combo: 0,
    maxCombo: 0,
    gameStatus: 'ready',
    timeRemaining: settings.gameDuration,
    lives: settings.startingLives,
    totalPopped: 0,
    totalMissed: 0,
    lastPopTime: 0,
  };
}

export function balloonReducer(state: InternalState, action: BalloonAction): InternalState {
  switch (action.type) {
    case 'RESET':
      return makeInitialState(action.difficulty, action.gridSize, action.highScore);

    case 'START':
      return { ...state, gameStatus: 'playing', lastPopTime: Date.now() };

    case 'SET_DIFFICULTY':
      // Changing difficulty resets the game (matches original initializeGame re-run behaviour)
      return makeInitialState(action.difficulty, state.gridSize, state.highScore);

    case 'SET_GRID_SIZE':
      return { ...state, gridSize: action.gridSize };

    case 'SPAWN_BALLOON':
      return { ...state, balloons: [...state.balloons, action.balloon] };

    case 'POP_BALLOON': {
      const balloon = state.balloons.find(b => b.id === action.balloonId);
      if (!balloon) return state;

      const withoutBalloon = state.balloons.filter(b => b.id !== action.balloonId);

      if (balloon.type === 'bomb') {
        const newLives = state.lives - 1;
        return {
          ...state,
          balloons: withoutBalloon,
          lives: newLives,
          combo: 0,
          gameStatus: newLives <= 0 ? 'gameOver' : state.gameStatus,
        };
      }

      // Good balloon — compute combo from reducer state (no stale closure)
      const timeSinceLastPop = action.now - state.lastPopTime;
      const newCombo = timeSinceLastPop < COMBO_WINDOW ? state.combo + 1 : 1;
      const basePoints = balloon.type === 'golden' ? POINTS.golden : POINTS.normal;
      const comboBonus = newCombo > 1 ? (newCombo - 1) * POINTS.combo : 0;

      return {
        ...state,
        balloons: withoutBalloon,
        score: state.score + basePoints + comboBonus,
        combo: newCombo,
        maxCombo: Math.max(state.maxCombo, newCombo),
        totalPopped: state.totalPopped + 1,
        lastPopTime: action.now,
      };
    }

    case 'EXPIRE_BALLOON': {
      const balloon = state.balloons.find(b => b.id === action.balloonId);
      if (!balloon) return state; // Already popped — no-op

      const withoutBalloon = state.balloons.filter(b => b.id !== action.balloonId);

      if (balloon.type === 'bomb') {
        // Bomb expired — no life penalty, but combo resets
        return { ...state, balloons: withoutBalloon, combo: 0 };
      }

      // Normal/golden missed
      const newLives = state.lives - 1;
      return {
        ...state,
        balloons: withoutBalloon,
        totalMissed: state.totalMissed + 1,
        lives: newLives,
        combo: 0,
        gameStatus: newLives <= 0 ? 'gameOver' : state.gameStatus,
      };
    }

    case 'TICK': {
      if (state.timeRemaining <= 1) {
        return { ...state, timeRemaining: 0, gameStatus: 'gameOver' };
      }
      return { ...state, timeRemaining: state.timeRemaining - 1 };
    }

    case 'LOAD_HIGH_SCORE':
      return { ...state, highScore: action.highScore };

    default:
      return state;
  }
}

interface UsePopBalloonsReturn {
  gameState: PopBalloonsState;
  handleBalloonPop: (balloonId: string) => void;
  startGame: () => void;
  resetGame: () => void;
  setDifficulty: (difficulty: Difficulty) => void;
  setGridSize: (gridSize: GridSize) => void;
}

export const usePopBalloons = (): UsePopBalloonsReturn => {
  const [state, dispatch] = useReducer(balloonReducer, makeInitialState('easy'));

  // stateRef — gives setTimeout / setInterval callbacks access to fresh state
  // without needing them in their dependency arrays
  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  const spawnTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const gameTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Tracks whether a tab-hide event stopped the timers (vs natural game over)
  const visibilityPausedRef = useRef(false);

  // ── Load high score whenever difficulty changes (includes mount) ──────────
  useEffect(() => {
    const saved = getHighScore(`${GAME_KEY}_${state.difficulty}`);
    dispatch({ type: 'LOAD_HIGH_SCORE', highScore: saved });
  }, [state.difficulty]);

  // ── Derive occupied positions from current state (replaces occupiedPositionsRef) ──
  const getRandomPosition = useCallback((): { row: number; col: number } | null => {
    const { balloons, gridSize } = stateRef.current;
    const occupied = new Set(balloons.map(b => `${b.position.row}-${b.position.col}`));
    const size = gridSizeSettings[gridSize].size;
    const available: { row: number; col: number }[] = [];

    for (let row = 0; row < size; row++) {
      for (let col = 0; col < size; col++) {
        if (!occupied.has(`${row}-${col}`)) available.push({ row, col });
      }
    }

    return available.length === 0 ? null : randomChoice(available);
  }, []);

  const getBalloonType = useCallback((difficulty: Difficulty): BalloonType => {
    const { bombChance, goldenChance } = difficultySettings[difficulty];
    const rand = Math.random();
    if (rand < bombChance) return 'bomb';
    if (rand < bombChance + goldenChance) return 'golden';
    return 'normal';
  }, []);

  // ── Spawn balloon (called from setInterval — reads fresh state via stateRef) ──
  const spawnBalloon = useCallback(() => {
    const position = getRandomPosition();
    if (!position) return; // Grid is full

    const { difficulty } = stateRef.current;
    const settings = difficultySettings[difficulty];
    const type = getBalloonType(difficulty);

    const balloon: Balloon = {
      id: `balloon-${Date.now()}-${Math.random()}`,
      position,
      type,
      color:
        type === 'golden'
          ? 'hsl(45, 100%, 60%)'
          : type === 'bomb'
            ? 'hsl(0, 0%, 30%)'
            : randomChoice(balloonColors),
      lifetime: settings.balloonLifetime,
      spawnTime: Date.now(),
    };

    dispatch({ type: 'SPAWN_BALLOON', balloon });

    // Auto-expire after lifetime — EXPIRE_BALLOON is a no-op if already popped
    setTimeout(() => {
      dispatch({ type: 'EXPIRE_BALLOON', balloonId: balloon.id });
    }, settings.balloonLifetime);
  }, [getRandomPosition, getBalloonType]);

  // ── Public callbacks ──────────────────────────────────────────────────────

  const handleBalloonPop = useCallback((balloonId: string) => {
    const balloon = stateRef.current.balloons.find(b => b.id === balloonId);
    if (!balloon) return;

    // Side-effects (sounds) happen before dispatch — keeps reducer pure
    if (balloon.type === 'bomb') {
      playSound('lose');
    } else {
      playSound(balloon.type === 'golden' ? 'collect' : 'pop');
    }

    dispatch({ type: 'POP_BALLOON', balloonId, now: Date.now() });
  }, []);

  const startGame = useCallback(() => {
    dispatch({ type: 'START' });
  }, []);

  const resetGame = useCallback(() => {
    const { difficulty, gridSize, highScore } = stateRef.current;
    dispatch({ type: 'RESET', difficulty, gridSize, highScore });
  }, []);

  const setDifficulty = useCallback((difficulty: Difficulty) => {
    dispatch({ type: 'SET_DIFFICULTY', difficulty });
  }, []);

  const setGridSize = useCallback((gridSize: GridSize) => {
    dispatch({ type: 'SET_GRID_SIZE', gridSize });
  }, []);

  // ── Spawn interval (re-runs only when play state or difficulty changes) ───
  useEffect(() => {
    if (state.gameStatus === 'playing') {
      spawnBalloon(); // Immediate first spawn

      spawnTimerRef.current = setInterval(() => {
        spawnBalloon();
      }, difficultySettings[state.difficulty].spawnRate);
    } else if (spawnTimerRef.current) {
      clearInterval(spawnTimerRef.current);
      spawnTimerRef.current = null;
    }

    return () => {
      if (spawnTimerRef.current) {
        clearInterval(spawnTimerRef.current);
        spawnTimerRef.current = null;
      }
    };
  }, [state.gameStatus, state.difficulty, spawnBalloon]);

  // ── Game countdown timer ──────────────────────────────────────────────────
  useEffect(() => {
    if (state.gameStatus === 'playing') {
      gameTimerRef.current = setInterval(() => {
        dispatch({ type: 'TICK' });
      }, 1000);
    } else if (gameTimerRef.current) {
      clearInterval(gameTimerRef.current);
      gameTimerRef.current = null;
    }

    return () => {
      if (gameTimerRef.current) {
        clearInterval(gameTimerRef.current);
        gameTimerRef.current = null;
      }
    };
  }, [state.gameStatus]);

  // ── Pause timers on tab hide; restart them when tab is shown again ────────
  // PopBalloons has no 'paused' gameStatus, so we manage the intervals directly.
  // stateRef gives fresh access to difficulty/gameStatus without re-registration.
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.hidden) {
        if (stateRef.current.gameStatus === 'playing') {
          visibilityPausedRef.current = true;
          if (spawnTimerRef.current) {
            clearInterval(spawnTimerRef.current);
            spawnTimerRef.current = null;
          }
          if (gameTimerRef.current) {
            clearInterval(gameTimerRef.current);
            gameTimerRef.current = null;
          }
        }
      } else if (visibilityPausedRef.current) {
        visibilityPausedRef.current = false;
        if (stateRef.current.gameStatus === 'playing') {
          spawnBalloon();
          spawnTimerRef.current = setInterval(
            spawnBalloon,
            difficultySettings[stateRef.current.difficulty].spawnRate,
          );
          gameTimerRef.current = setInterval(() => {
            dispatch({ type: 'TICK' });
          }, 1000);
        }
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [spawnBalloon]); // spawnBalloon is stable (empty-dep useCallback chain)

  // ── Persist high score on game over ──────────────────────────────────────
  useEffect(() => {
    if (state.gameStatus === 'gameOver' && state.score > state.highScore) {
      saveHighScore(`${GAME_KEY}_${state.difficulty}`, state.score);
      dispatch({ type: 'LOAD_HIGH_SCORE', highScore: state.score });
    }
  }, [state.gameStatus, state.score, state.highScore, state.difficulty]);

  // ── Build public state (omit internal lastPopTime field) ─────────────────
  const gameState: PopBalloonsState = {
    balloons: state.balloons,
    score: state.score,
    highScore: state.highScore,
    combo: state.combo,
    maxCombo: state.maxCombo,
    gameStatus: state.gameStatus,
    difficulty: state.difficulty,
    gridSize: state.gridSize,
    timeRemaining: state.timeRemaining,
    lives: state.lives,
    totalPopped: state.totalPopped,
    totalMissed: state.totalMissed,
  };

  return { gameState, handleBalloonPop, startGame, resetGame, setDifficulty, setGridSize };
};

